const CHAPTERS: VizChapter[] = [{"id":"data-ch01","subj":"data","title":"NumPy 基础：ndarray 与向量化","summary":"为什么需要 ndarray（同构连续内存 + 向量化 vs Python list 的对象开销）；dtype 与内存布局（C/F order）；创建与形状变换（reshape/ravel/transpose/expand_dims）；索引与…","concepts":[{"id":"data-ch01/01-ndarray-memory","file":"01-ndarray-memory.md","title":"ndarray 的内存布局：为什么它比 list 快两个数量级","kind":"stack","secs":[{"h":"1. 先看一个反直觉的事实","s":"arr 存 1000 万个 int64，占 80 MB（10^7 × 8 字节，连续）。","c":{"lang":"python","code":"import sys, numpy as np\nlst = list(range(10_000_000))\narr = np.arange(10_000_000, dtype=np.int64)"}},{"h":"2. list 的内存模型：指针数组 + 散落的对象","s":"1. 空间：8 字节数据 → 36+ 字节开销（4.5 倍）；","c":{"lang":"text","code":"list（CPython）\n┌───────────────────────────────┐\n│ 指针数组（连续，存 PyObject*） │\n│  [0] ──→ PyObject 1 (28B)      │  ← 散落在堆上，地址随机\n│  [1] ──→ PyObject 2 (28B)      │\n│  [2] ──→ PyObject 3 (28B)      │\n│  ...                           │\n└───────────────────────────────┘\n\n…"}},{"h":"3. ndarray 的内存模型：一块连续裸内存 + 元数据","s":"","c":{"lang":"text","code":"np.ndarray 对象（元数据，很小）\n┌──────────────────────────────────────────┐\n│ data   : 0x7f...  ← 指向数据区起点        │\n│ dtype  : int64    ← 全体元素同一类型      │\n│ shape  : (10000000,)                      │\n│ strides: (8,)     ← 沿第 0 维走一步的字节数│\n└──────────────────────────────────────────┘\n            ↓\n数据区（连续、无对象头、无指针）\n…"}},{"h":"4. strides：NumPy 最精妙的设计","s":"strides 是「沿某个维度移动 1 个单位，需要在内存中跳过多少字节」。它是理解","c":{"lang":"python","code":"a = np.arange(12, dtype=np.int64).reshape(3, 4)\na.shape    # (3, 4)\na.strides  # (32, 8)   ← 行方向跳 32 字节（4 个 int64），列方向跳 8 字节\n\nb = a.T\nb.shape    # (4, 3)\nb.strides  # (8, 32)   ← 只是把 strides 换了顺序！数据区完全没动"}},{"h":"5. C order vs F order","s":"用 F order 存储会显著更快——因为沿列方向是连续的，预取器能提前加载。","c":null},{"h":"6. dtype 的选择是性能与内存的第一杠杆","s":"现代 GPU 的 float32 吞吐通常是 float64 的 2~32 倍（消费级显卡 FP64 被刻意阉割）。","c":null},{"h":"7. 一句话总结","s":"","c":null}]},{"id":"data-ch01/02-views-copies-broadcast","file":"02-views-copies-broadcast.md","title":"视图与拷贝、广播机制：NumPy 最容易踩坑的两块","kind":"compare","secs":[{"h":"1. 视图（view）vs 拷贝（copy）","s":"判断方法（两个都该会）：","c":{"lang":"python","code":"b = a[::2]\nb.base is a            # True → b 是 a 的视图\nnp.shares_memory(a, b) # True → 共享内存\n\nc = a[[0, 2, 4]]       # 花式索引\nc.base is a            # False（可能是 None 或临时数组）\nnp.shares_memory(a, c) # False → 拷贝"}},{"h":"2. 广播（broadcasting）：三条规则","s":"1. 相等；或","c":{"lang":"python","code":"A.shape == (3, 4)\nB.shape == (4,)      # 尾维 4 == 4  ✓  → 结果 (3, 4)\nC.shape == (3, 1)    # 尾维 1 → 扩展成 4 ✓ → 结果 (3, 4)\nD.shape == (3,)      # 尾维 3 vs 4 ✗  → 报错（不是 (3,4) 与 (3,) 的关系！）"}},{"h":"3. 广播是「零拷贝」的：靠 strides = 0 实现","s":"广播不会真的把 1 维复制成 4 份。NumPy 的做法是把该维的 stride 设为 0：","c":{"lang":"python","code":"a = np.arange(4)                  # shape (4,), strides (8,)\nb = np.broadcast_to(a, (3, 4))\nb.strides                         # (0, 8)  ← 第 0 维 stride = 0：走一步地址不变"}},{"h":"4. 什么时候该主动 .copy()","s":"这是典型的「内存泄漏」错觉）；","c":null},{"h":"5. 一句话总结","s":"","c":null}]},{"id":"data-ch01/03-ufunc-vectorization","file":"03-ufunc-vectorization.md","title":"ufunc 与向量化：把循环从 Python 搬进 C","kind":"flow","secs":[{"h":"1. ufunc 是什么","s":"np.add / np.sin / np.exp / np.sqrt / 比较运算符 > 都是 ufunc。","c":{"lang":"python","code":"a + b        # 语法糖，等价于 np.add(a, b)，后者是 ufunc\nnp.sqrt(a)   # ufunc"}},{"h":"2. 三个数量级的差距从哪来","s":"实测（N = 10⁶，本机 3.13）：","c":{"lang":"text","code":"Python for 循环      ~100 ms\nlist comprehension   ~50 ms\nnp.sum(a)            ~1 ms     ← 约 100 倍"}},{"h":"3. ufunc 的四类常用方法","s":"原因：a[idx] += 1 展开为「取值 → 加 → 赋值」，重复索引的三次加法各自基于同一个旧值，","c":{"lang":"python","code":"np.add.reduce(a)      # 归约：等价于 np.sum(a)\nnp.add.accumulate(a)  # 累积：等价于 np.cumsum(a)\nnp.add.outer(a, b)    # 外积：得到 (len(a), len(b)) 的全体两两之和\nnp.add.at(a, idx, v)  # 无缓冲就地加：处理重复索引时结果正确（a[idx] += v 会丢重复项）"}},{"h":"4. 用 np.where 取代 Python 层 if","s":"所以若某分支会除零，要先用 np.errstate 或改写为 np.divide(..., where=...)：","c":{"lang":"python","code":"# 慢 + 啰嗦\nout = np.empty_like(x)\nfor i in range(len(x)):\n    out[i] = x[i] * 2 if x[i] > 0 else 0\n\n# 快 + 简洁\nout = np.where(x > 0, x * 2, 0)"}},{"h":"5. 聚合的 axis 语义（务必形成肌肉记忆）","s":"","c":{"lang":"python","code":"a.shape == (3, 4)\na.sum()         # 标量（全体求和）\na.sum(axis=0)   # shape (4,)  —— 沿行方向压掉第 0 维 → 每列的和\na.sum(axis=1)   # shape (3,)  —— 沿列方向压掉第 1 维 → 每行的和\na.sum(axis=(0,1))  # 标量（多轴聚合）\na.sum(keepdims=True)  # shape (1,1) —— 保留被压掉的维度，便于后续广播"}},{"h":"6. 一句话总结","s":"","c":null}]},{"id":"data-ch01/04-indexing-and-mask","file":"04-indexing-and-mask.md","title":"索引体系：基本切片、布尔掩码与花式索引","kind":"flow","secs":[{"h":"1. 三种索引，三种语义","s":"NumPy 只好新开内存把挑出来的值拷进去。这也意味着：","c":{"lang":"python","code":"a[a > 0] = 99     # 这不是「赋值到视图」，而是 a.__setitem__(mask, 99)，能正常改到 a\nb = a[a > 0]\nb[:] = 99         # b 是 copy，改 b 不会影响 a"}},{"h":"2. 花式索引的配对规则（容易记反）","s":"想要「取行列交叉的子矩阵」必须用 np.ix_ 或分两次索引。","c":{"lang":"python","code":"a.shape == (3, 4)\na[[0, 2], [1, 3]]    # 结果是 [a[0,1], a[2,3]] 两个标量 —— 按下标「配对」取点\na[[0, 2]][:, [1, 3]] # 或 a[np.ix_([0,2],[1,3])] —— 取子矩阵 shape (2,2)"}},{"h":"3. 布尔索引的组合与陷阱","s":"转成单个 bool，而数组的真值是未定义的。而且因为 & 的优先级低于比较运算符… 实际是","c":{"lang":"python","code":"mask = (a > 0) & (a < 10)      # ✓ 用 & 且必须加括号（& 优先级高于比较？不，是低于）\n# 错误写法：(a > 0) and (a < 10)  → ValueError: 真值不明确"}},{"h":"4. 用布尔索引做数据清洗（数据科学日常）","s":"","c":{"lang":"python","code":"data = data[~np.isnan(data)]                 # 去 NaN\ndata = data[(data > lo) & (data < hi)]       # 截尾去异常值\nlabels = labels[np.isin(labels, valid_set)]  # 按白名单过滤"}},{"h":"5. np.where 的两种用法","s":"第一个用法在做「找出异常值位置」时很有用：","c":{"lang":"python","code":"np.where(cond)           # 返回满足条件的下标元组，等价于 np.nonzero(cond)\nnp.where(cond, x, y)     # 三元选择：cond 为真取 x，否则取 y（支持广播）"}},{"h":"6. 视图 vs 拷贝的性能含义","s":"优化手段是一次性算好索引数组，或用 np.take(a, idx, axis=0)（语义相同但有时更快）。","c":null},{"h":"7. 一句话总结","s":"","c":null}]},{"id":"data-ch01/05-ndarray-practical-recipes","file":"05-ndarray-practical-recipes.md","title":"凯喵实战手记 · ndarray 的内存真相：视图、步长与掩码","kind":"flow","secs":[{"h":"现场 1：ndarray 是「数据 + 形状 + 步长」","s":"ndarray 本身不存数据，它持有一个指向缓冲区的指针，加上 shape（各维长度）、strides（每维跨多少字节）、dtype（元素类型）。凯喵：理解这三件套，你才知道「同一个缓冲区可以被看成不同形状」，也就理解了视图为什么零拷贝…","c":{"lang":"python","code":"import numpy as np\na = np.arange(12).reshape(3, 4)\nprint(a.strides)   # 每维步长（字节）"}},{"h":"现场 2：C 顺序与 F 顺序决定遍历快慢","s":"默认是 C 顺序（行优先），沿最后一维连续；F 顺序（列优先）沿第一维连续。凯喵：按哪种顺序访问，就决定了缓存命中率。对 C 顺序数组按行遍历最快，按列遍历会频繁跨行跳，慢好几倍。","c":{"lang":"python","code":"c = np.ones((1000, 1000), order='C')\nf = np.ones((1000, 1000), order='F')"}},{"h":"现场 3：切片返回视图，改它就改原数组","s":"a[0:2]、a[:, 1] 这类基础切片返回视图，共享底层内存。凯喵：这是 NumPy 高效的原因，也是「明明拷贝了怎么原数组也变了」的根源。需要独立副本必须显式 .copy()。","c":{"lang":"python","code":"v = a[0:2]\nv[0, 0] = 99      # a 也会变"}},{"h":"现场 4：花式索引与布尔索引返回拷贝","s":"a[[0, 2]]（整数数组索引）和 a[a > 0]（布尔索引）返回的是拷贝，不是视图。凯喵：所以「用布尔索引筛选后改值，原数组不变」是正常的，别以为哪里写错了；要改原数组，就用 np.where 加原地赋值。","c":{"lang":"python","code":"mask = a > 5\nsub = a[mask]     # 拷贝\nsub[:] = 0        # a 不变"}},{"h":"现场 5：reshape 多数情况是视图","s":"只要内存连续，reshape 返回视图；不连续时会先拷贝。凯喵：a.reshape(...) 后改元素可能影响原数组，取决于是否连续。不确定时用 a.base is not None 判断是否视图。","c":{"lang":"python","code":"b = a.reshape(2, 6)\nprint(b.base is a)   # True 表示视图"}},{"h":"现场 6：transpose 只改步长，不搬数据","s":"转置只是把 strides 换一下，零拷贝。凯喵：所以转置后的数组「逻辑上是转置的，物理上还是原顺序」，此时它不连续，某些操作会变慢或触发拷贝。需要连续内存时用 np.ascontiguousarray。","c":{"lang":"python","code":"t = a.T\nprint(t.flags['C_CONTIGUOUS'])   # False"}},{"h":"现场 7：广播不复制数据，但结果会实体化","s":"广播让不同形状的数组「看起来」能运算，但结果数组是真实分配的。凯喵：广播本身零拷贝，但 a + b 产生的新数组占内存；大数组广播运算要警惕中间结果的内存峰值，必要时分块。","c":{"lang":"python","code":"x = np.arange(3)[:, None]   # (3,1)\ny = np.arange(4)[None, :]   # (1,4)\nz = x + y                   # (3,4)，真实分配"}},{"h":"现场 8：ufunc 是逐元素运算的引擎","s":"np.add、np.multiply 这些 ufunc 在 C 层循环，比 Python 循环快得多，还能用 out= 复用缓冲区。凯喵：向量化不是「写法好看」，而是真正把循环下沉到编译代码里，同时避免 Python 解释器开销。","c":{"lang":"python","code":"np.multiply(a, 2, out=a)   # 原地，不分配新数组"}},{"h":"现场 9：astype 默认产生拷贝","s":"a.astype(np.float64) 会新建数组，即使类型相同也可能拷贝。凯喵：需要视图时传 copy=False，但要注意很多场景它仍会拷贝；想要独立副本就显式 .copy()，别依赖默认行为。","c":{"lang":"python","code":"b = a.astype(np.float64)            # 拷贝\nc = a.astype(np.float64, copy=False) # 尽量不拷，但不保证"}},{"h":"现场 10：布尔掩码是最常用的筛选方式","s":"a[a > 0] 返回满足条件的元素拷贝。凯喵：条件可以组合，用 &、|、~，注意每个条件要加括号，Python 的运算符优先级会让 a > 0 & a < 5 变成意外结果。","c":{"lang":"python","code":"sel = a[(a > 0) & (a < 5)]"}},{"h":"现场 11：np.where 做条件赋值而不用循环","s":"np.where(cond, x, y) 向量化地按条件选值。凯喵：凡是「根据条件逐元素赋值」的循环，先想 np.where，通常能快几十上百倍，代码也更短。","c":{"lang":"python","code":"out = np.where(a > 0, a, 0)   # 负数置零"}},{"h":"现场 12：小数组向量化可能更慢","s":"元素数少于约一千时，NumPy 每次调用的固定开销占比过大，纯 Python 循环可能反超。凯喵：别迷信「向量化一定快」，小数据先测一下；大数据才真正体现优势。","c":null},{"h":"现场 13：np.save 保留 dtype 与形状","s":"存数值数组用 .npy 而不是 CSV，前者保留 dtype、shape、字节序，加载极快。凯喵：to_csv 存数值矩阵既慢又丢类型，只适合给人看，不适合给程序读。","c":{"lang":"python","code":"np.save('a.npy', a)\na2 = np.load('a.npy')"}},{"h":"现场 14：内存映射处理超大数组","s":"数据大到装不下内存时，用 mmap_mode 只映射不加载，按需读取。凯喵：这是处理超大数据集的标准手法，配合分块计算能处理远超内存的数据。","c":{"lang":"python","code":"big = np.load('big.npy', mmap_mode='r')\nchunk = big[0:1000]"}},{"h":"凯喵叮嘱：先问视图还是拷贝","s":"最后叮嘱一句：每次对 ndarray 做切片、变形、转置之后，先问自己「这是视图还是拷贝」。凯喵见过太多「改着改着原数据也变了」或者「改了副本原数据没变」的困惑，根子都在这一句。","c":null},{"h":"🧑‍💻 程序员视角","s":"凯喵处理一个 4GB 的 CSV，用切片取了子集再原地修改，结果原始数组被改了——arr[1:3] 返回的是视图（共享内存），要拷贝必须 .copy()。反过来，花式索引 arr[[0, 2, 5]] 返回的是拷贝，改它不影响原数组，这…","c":null},{"h":"🎓 博士生视角","s":"ndarray 的内存模型是「一段连续缓冲区 + dtype + shape + strides」，任何「形状变化」只要能用 strides 表达就零拷贝（reshape、transpose、切片），否则必须复制（花式索引、copy）…","c":null},{"h":"📚 考研者视角","s":"数据分析岗面试常问：","c":null}]}],"exams":[{"kind":"choice","q":"哪些操作返回视图","stem":"对二维数组 a = np.arange(12).reshape(3,4)，下列哪些操作一定返回视图（与 a 共享内存）？","opts":[{"k":"A","t":"a[0]"},{"k":"B","t":"a[:, 0]"},{"k":"C","t":"a[a > 5]"},{"k":"D","t":"a.T"}],"ans":"ABD","why":"视图 vs 拷贝是 NumPy 内存正确性的第一道关。"},{"kind":"fix_error","q":"广播失败的归一化写法","stem":"想把矩阵每一列做标准化（每列减去该列均值再除以标准差），下面代码报错： python x = np.random.randn(100, 5) z = (x - x.mean(axis=0)) / x.std(axis=0) 如果矩阵是 x.shape == (5, 100)（即每行是一个样本、每列是特征），有人写成 x - x.mean(axis=1) 也报错。请分别指出问题并给出正确写法。","opts":[],"ans":"# 情形一（列是特征）：axis=0 得到 shape (5,)，尾维 5 与 100 不匹配 → 报错 z = (x - x.mean(axis=0)) / x.std(axis=0) # ValueError z = (x - x.mean(axis=0, keepdims=True)) / x.std(axis=…","why":"广播从尾维对齐；keepdims 是避免手工升维的利器。"},{"kind":"output","q":"重复索引的就地加为何丢数据","stem":"执行下面两段代码，分别输出什么？为什么不同？ python a = np.zeros(3); idx = np.array([0, 0, 0, 1]) a[idx] += 1 print(a) b = np.zeros(3) np.add.at(b, idx, 1) print(b)","opts":[],"ans":"","why":"花式索引与就地运算的经典陷阱，做直方图/计数时必踩。"},{"kind":"coding","q":"重塑矩阵（reshape 与 C 顺序）","stem":"给定矩阵与目标行列数，若元素总数匹配则重塑，否则原样返回。用 NumPy 的 reshape 语义实现。","opts":[],"ans":"np.arange(mn).reshape(r, c) # 按行优先（C order）填充","why":"理解 reshape 的填充顺序（C vs F）是向量化思维的起点。"},{"kind":"coding","q":"转置矩阵（strides 与视图）","stem":"求矩阵转置。用 NumPy 实现并说明：转置操作是否真的搬动了数据？","opts":[],"ans":"a.T # 只交换 strides，O(1) 视图，不搬数据","why":"strides 是理解 NumPy 零成本变形的钥匙。"},{"kind":"coding","q":"旋转图像（原地与视图的关系）","stem":"将 n×n 矩阵顺时针旋转 90 度。用 NumPy 实现（允许 np.rot90），并讨论它是否原地。","opts":[],"ans":"np.rot90(a, k=-1) # k=-1 表示顺时针 90 度；返回视图","why":"区分「语义上旋转」与「物理上原地」——NumPy 倾向前者（返回视图）。"}],"works":[{"h":"以为切片是拷贝，改了切片污染源数据","d":"b = a[::2] 是 view，b[:] = 0 会改到 a。判断用 b.base is a 或 np.shares_memory(a, b)；要独立副本请显式 .copy()。"},{"h":"用 and / or 组合布尔掩码","d":"数组真值未定义，会抛 ValueError: 真值不明确。必须用按位运算符 & | ~，且每个子表达式都要加括号。"},{"h":"a[idx] += 1 在 idx 有重复时结果偏小","d":"它展开为「取值 → 加 → 赋值」，重复索引的多次加法都基于同一个旧值，最后只写回一次。正确写法是 np.add.at(a, idx, 1)。"},{"h":"聚合后忘记升维导致广播失败","d":"a.mean(axis=1) 得到 shape (n,)，直接与 a（shape (n,m)）相减会报错。要用 a m[:, None]，或聚合时直接 keepdims=True。"},{"h":"以为 (3,) 能和 (3,4) 广播","d":"广播从尾维对齐，(3,) 的尾维 3 与 (3,4) 的尾维 4 不匹配，必然报错。要在尾部插维：v[:, None]。"},{"h":"a[[0,2],[1,3]] 想要子矩阵却拿到两个标量","d":"多个花式索引在同一对方括号内是「按下标配对取点」。取子矩阵应用 a[np.ix_([0,2],[1,3])] 或分两次索引。"},{"h":"链式运算产生大量临时数组撑爆内存","d":"ab + c/d ef 会产生多个与操作数等大的临时数组。大数组应分块处理，或用 out= 参数复用缓冲区。"},{"h":"以为 a.T 会搬数据","d":"转置只是交换 strides，是 O(1) 的 view。但它会让数组失去 C 连续性，后续逐元素运算可能变慢；需要连续布局时再 .copy()。"}],"asks":[{"q":"为什么 NumPy 数组比 Python list 快几十到上百倍？请具体说明是哪几个因素。","a":"不要只答「因为它是 C 写的」，至少有四个独立因素： 1. 内存布局：list 是「指针数组 + 散落的 PyObject」，每个 int 约占 28 字节对象加 8 字节指针；ndarray 是一块连续裸内存，一个 int64 就只占 8 字节。 2. cache 局部性：连续内存让 CPU 预取器能提前加载下一个 cache line；list 每次解引用跳到随机地址，几乎必然 cache m…","fu":["什么情况下 NumPy 反而不如纯 Python？","如何避免链式运算产生大量临时数组？"],"tag":"字节跳动/阿里巴巴"},{"q":"切片到底返回视图还是拷贝？怎么判断？有哪些例外？","a":"规律：凡是结果能用「起点 + 步长（strides）」描述的，就是视图（共享内存）；只要需要「按索引挑元素」，就一定是拷贝。 | 返回视图 | 返回拷贝 | |---|---| | 基本切片 a[1:5]、a[::2] | 布尔索引 a[a>0] | | a.T（只交换 strides） | 花式索引 a[[0,2,4]] | | 连续时的 reshape | 非连续时的 reshape/rave…","fu":["a.T 的时间复杂度是多少？为什么？","为什么 flatten() 一定拷贝而 ravel() 不一定？"],"tag":"腾讯/美团"},{"q":"广播规则是什么？为什么 (3,) 不能和 (3,4) 广播？","a":"三条规则，从尾维（最右）开始逐维对齐，两个维度相容当且仅当：相等 / 其中一个是 1 / 其中一个不存在。 (3,) 与 (3,4)：尾维分别是 3 与 4，既不相等也没有 1 → 不相容，报错。 很多人误以为 (3,) 会沿行广播，那需要的是 (3,1)：尾维 1 可扩成 4，首维 3 == 3，结果 (3,4)。 正确写法：v[:, None]（或 v.reshape(3,1)、或聚合时 ke…","fu":["广播后的数组还连续吗？","(2,1,3) 和 (4,3) 能广播吗？结果 shape 是什么？"],"tag":"字节跳动/百度"},{"q":"a[idx] += 1 在 idx 含重复下标时结果为什么不对？怎么修？","a":"现象：a = np.zeros(3); idx = np.array([0,0,0,1]); a[idx] += 1 得到 [1,1,0]，而非直觉上的 [3,1,0]。 原因：Python 把 a[idx] += 1 展开成三步： tmp = a.__getitem__(idx) # 取值 → [0, 0, 0, 0] tmp = tmp.__iadd__(1) # 加 → [1, 1, 1,…","fu":["np.bincount 和 np.add.at 各适合什么场景？","为什么不能简单地用花式索引赋值来修复？"],"tag":"字节跳动/量化私募"}]},{"id":"data-ch02","subj":"data","title":"NumPy 进阶：广播、随机与性能","summary":"广播规则的逐步推导与常见踩坑（形状对齐、维度扩展）；花式索引与布尔索引、np.where/np.select；结构化数组与记录数组；新式随机数 API（Generator/BitGenerator）；stride 与内存视图、as_stri…","concepts":[{"id":"data-ch02/01-broadcasting-rules","file":"01-broadcasting-rules.md","title":"广播规则与内存爆炸陷阱","kind":"stack","secs":[{"h":"一、广播的三条规则与形状推导","s":"广播（broadcasting）是 NumPy 让形状不同但兼容的数组参与逐元素运算的机制。","c":{"lang":"text","code":"例1: (3,1) + (3,)   →  (3,1) 与 (1,3) 对齐? 不，(3,) 补成 (1,3)\n      (3,1) 尾维1, (1,3) 尾维3 → 不相容? \n      —— 正确推导：(3,1) 与 (3,) 从尾对齐：1 vs 3 → 1 可扩成 3 → (3,3)\n例2: (2,1,3) + (4,3) → 补维 (1,4,3) 与 (2,1,3)：尾维3==3、1==1、2==1(扩) → (2,4,3)\n例3: (3,) + (3,4)   → 尾维 3 vs 4 既不等的也不是 1 → ValueError"}},{"h":"二、广播的内存零拷贝本质与「内存爆炸」陷阱","s":"广播在运算时是零拷贝的，但一旦物化（np.array、np.broadcast_to 后取副本、+ 的结果本身是一个新数组）就会真正分配内存。","c":{"lang":"text","code":"base = np.arange(4)                 # 32 字节\nbig  = np.broadcast_to(base, (10_000_000, 4))   # 仍是 32 字节（view，stride[0]=0）\nmat  = np.array(big)                # 物化 → 320 MB！内存瞬间爆炸"}}]},{"id":"data-ch02/02-random-api","file":"02-random-api.md","title":"随机数：新旧 API 与可复现性","kind":"flow","secs":[{"h":"一、旧式 np.random 全局 API 与新式 Generator","s":"旧式接口（np.random.seed / np.random.rand / np.random.randn）操作一个进程级全局 RandomState；","c":{"lang":"text","code":"# 旧式：全局可变状态，任何地方调用都会推进同一条流\nnp.random.seed(0)\na = np.random.randn(3)\n\n# 新式：封装在 Generator 实例里，互不干扰\nrng = np.random.default_rng(42)\nb = rng.standard_normal(3)\nc = rng.integers(0, 10, size=5)"}},{"h":"二、可复现性、随机流与并行","s":"同一个种子产生同一条随机流；不同种子产生相互独立的流；Generator 实例各自维护游标，调用顺序决定后续值。","c":{"lang":"text","code":"rng_a = np.random.default_rng(7)\nrng_b = np.random.default_rng(7)\nrng_a.standard_normal(3) == rng_b.standard_normal(3)   # True（同流）\n\ng1 = np.random.default_rng(1); g2 = np.random.default_rng(2)\ng1.standard_normal(3) != g2.standard_normal(3)         # True（异流）"}}]},{"id":"data-ch02/03-performance-vectorization","file":"03-performance-vectorization.md","title":"性能：向量化、einsum 与 stride tricks","kind":"compare","secs":[{"h":"一、向量化 vs 显式循环：为什么快、何时不快","s":"向量化把逐元素的 Python 循环「下沉」到 C 层的一个 ufunc 调用里，消除解释器开销、利用连续内存局部性与 SIMD。","c":{"lang":"text","code":"# 慢：Python 解释器逐次执行 2e6 次\ns = 0.0\nfor i in range(N):\n    s += a[i] * b[i]\n# 快：一次 ufunc 调用\ns = np.dot(a, b)"}},{"h":"二、np.einsum 与 stride tricks：零拷贝的张量收缩","s":"np.einsum('ij,jk->ik', A, B) 用下标标记描述任意张量收缩，避免显式中间数组；np.lib.stride_tricks 则直接操控 strides 做零拷贝视图。","c":{"lang":"text","code":"# 批量矩阵乘：'bij,bjk->bik' 一次完成，无需 for 循环\nZ = np.einsum('bij,bjk->bik', X, Y)\n\n# 滑动窗口零拷贝（不复制原数组）\nfrom numpy.lib.stride_tricks import sliding_window_view\nw = sliding_window_view(np.arange(10), 3)   # shape (8, 3)，是 view"}}]},{"id":"data-ch02/04-memory-layout-dtype","file":"04-memory-layout-dtype.md","title":"内存布局（C/F order）与 dtype 精度溢出","kind":"stack","secs":[{"h":"一、C order 与 F order：连续性与遍历缓存友好性","s":"","c":{"lang":"text","code":"a = np.arange(12).reshape(3,4)\na.flags['C_CONTIGUOUS']       # True\na.T.flags['F_CONTIGUOUS']     # True（转置后是 F 连续）\na.T.flags['C_CONTIGUOUS']     # False"}},{"h":"二、dtype 精度与溢出：float32 误差、整数回绕、浮点 inf","s":"","c":{"lang":"text","code":"a = np.array([127], dtype=np.int8) + 1      # -128（回绕）\nu = np.array([255], dtype=np.uint8) + 1     # 0（回绕）\nbig = np.float64(1.7e308) * 10              # inf"}}]},{"id":"data-ch02/05-numpy-practical-recipes","file":"05-numpy-practical-recipes.md","title":"凯喵实战手记 · NumPy 广播、随机与向量化的「性能陷阱」","kind":"flow","secs":[{"h":"现场 1：广播规则是「从尾轴对齐」","s":"广播从最后一维往前对齐，某一维相等或其中一方为 1 才能扩。凯喵：遇到广播报错，画个 shape 从右往左比，哪维不等且非 1 就炸。","c":{"lang":"python","code":"import numpy as np\na = np.zeros((3, 4))\nb = np.array([1, 2, 3, 4])      # shape (4,)\na + b                           # OK: b 在尾轴对齐，广播成 (3,4)\nc = np.array([1, 2, 3])         # shape (3,)\na + c                           # ValueError: 尾轴 4 vs 3 对不上"}},{"h":"现场 2：广播悄悄制造超大数组","s":"广播不会真复制数据，但运算结果会实例化巨大数组。凯喵：在维度很高的循环里慎用广播生成中间大数组，必要时分块或换 einsum/outer 的惰性思路。","c":{"lang":"python","code":"x = np.arange(1000)[:, None]   # (1000, 1)\ny = np.arange(1000)[None, :]   # (1, 1000)\nz = x + y                      # (1000, 1000)，一千万元素凭空出现"}},{"h":"现场 3：随机不可复现——忘了固定 seed","s":"np.random.seed 设的是全局随机状态，多线程/多模块互相踩，结果不稳健。凯喵：现代用 rng = np.random.default_rng(42) 拿独立 Generator，每次实验用同一个 rng，复现性有保障且不污染…","c":{"lang":"python","code":"np.random.seed(42)             # 旧 API，仅影响全局状态\nprint(np.random.rand())"}},{"h":"现场 4：np.random.choice 不放回采样","s":"需要「不放回」抽样必须 replace=False，否则可能重复。凯喵：做交叉验证/抽样时务必确认 replace 语义，否则评估结果有偏。","c":{"lang":"python","code":"rng = np.random.default_rng(0)\nsample = rng.choice(10, size=5, replace=False)  # 不放回，元素不重复"}},{"h":"现场 5：向量化不是银弹，小数组反而慢","s":"NumPy 每次调用有约 1μs 固定开销，且向量化一次性分配等大结果数组。凯喵：大数组（万级以上）上 ufunc，小数组别硬凹向量化，反而更清晰。","c":{"lang":"python","code":"# 元素 < ~1000 时，Python 循环可能和向量化差不多甚至更快（省去分配开销）\nfor i in range(50):\n    out[i] = a[i] * 2   # 小数组直接循环也行"}},{"h":"现场 6：einsum 默认不优化","s":"朴素 einsum 对复杂收缩可能很慢。凯喵：涉及两个以上张量收缩、或维度较大时，加 optimize=True（或 optimize='optimal'），大张量尤其要开。","c":{"lang":"python","code":"np.einsum('ij,jk->ik', A, B)            # 朴素实现，可能退化成低效循环\nnp.einsum('ij,jk->ik', A, B, optimize=True)  # 触发最优收缩顺序搜索（类似矩阵链乘 DP）"}},{"h":"现场 7：链式运算撑爆内存","s":"多个等大操作数连续运算会产生多个中间临时数组，内存峰值可能翻倍甚至更多。凯喵：大数组分块处理，或用 out= 复用缓冲区（np.multiply(a, b, out=tmp)），或拆成原地步骤降低峰值。","c":{"lang":"python","code":"res = a * b + c / d - e * f   # 每一步都生成与操作数等大的临时数组"}},{"h":"现场 8：C 顺序 vs F 顺序影响性能","s":"NumPy 默认 C 顺序（行优先）。连续访问沿最后一个轴最快；跨轴遍历会触发 cache miss。凯喵：需要频繁按某轴运算时，用 np.ascontiguousarray 整理内存布局，或用 np.transpose 后确保连续。","c":{"lang":"python","code":"arr = np.ones((1000, 1000), order='C')   # 行优先\narr.T.dot(arr)  # 转置后是 F 顺序，某些 BLAS 调用可能非最优"}},{"h":"现场 9：dtype 混用悄悄升/降级","s":"整数相除得浮点；astype 到整型会截断而非四舍五入。凯喵：关注 dtype，需要四舍五入用 np.round 再转；混合类型运算会按「安全向上」规则升型，留意内存占用。","c":{"lang":"python","code":"a = np.array([1, 2, 3])\nb = a / 2            # 结果是 float64，不是 int\nc = np.array([1.0, 2.0]).astype(np.int32)  # 截断小数部分"}},{"h":"现场 10：视图 vs 拷贝（reshape 不总是复制）","s":"基础切片/reshape 多返回视图（共享内存），花式索引/布尔索引返回拷贝。凯喵：要独立副本显式 .copy()，别假设「改一个不影响另一个」踩内存共享的坑。","c":{"lang":"python","code":"v = a.reshape(2, 3)   # 通常返回视图，改 v 影响 a\nc = a[::2].copy()     # 花式索引/布尔索引返回拷贝"}},{"h":"现场 11：用 np.where 替代循环条件赋值","s":"向量化的条件选择用 np.where / np.select，避免逐元素 Python 循环。凯喵：凡是「按条件改值」的 for 循环，先想 np.where，性能通常提升百倍。","c":{"lang":"python","code":"out = np.where(x > 0, x, 0)   # 比 for 循环快几个数量级"}},{"h":"现场 12：内存布局与 np.save/内存映射","s":"大数组用 .npy 而非 CSV（省解析、保类型）；超大数据集用 mmap_mode 做内存映射，避免 OOM。凯喵：数据持久化别用 to_csv 存数值矩阵，信息全丢还慢。","c":{"lang":"python","code":"np.save('a.npy', arr)                 # 保留 dtype 与 shape，加载极快\nmm = np.load('big.npy', mmap_mode='r')  # 内存映射，不一次性读入内存"}},{"h":"凯喵复盘：NumPy 的性能来自「内存布局」，不是「语法糖」","s":"这 12 个现场，凯喵最想强调的一点：很多人以为「用了 NumPy 就自动快」，结果反而写出比纯 Python 还慢、或者内存炸掉的代码。真相是，NumPy 的优势来自连续内存 + 编译好的 C 内核 + 向量化批量运算，任何破坏这三条…","c":null},{"h":"凯喵速记：NumPy 的三条性能底线","s":"只记三句也能写出又快又稳的分析代码：第一，实验用 np.random.default_rng(seed) 固定随机源，结果可复现，别用全局 seed 互相踩；第二，关注 dtype 与「截断 vs 四舍五入」，关键转换显式指定类型；第三…","c":null},{"h":"🧑‍💻 程序员视角","s":"凯喵用 (a[:, None] - b[None, :]) 算两万乘两万的差值矩阵，机器直接 OOM——广播不报错，它默默分配了 3.2GB。正确做法是分块计算或者用 scipy.spatial.distance.cdist。另一个坑是…","c":null},{"h":"🎓 博士生视角","s":"广播的规则可形式化为「从尾部对齐，逐维比较，相等或其一为 1 则可广播」，其代价是把「显式复制」变成「stride 为 0 的虚拟扩展」——只要后续操作不强制物化，就真的不占内存；但一旦参与需要连续内存的运算（如某些 BLAS 调用）…","c":null},{"h":"📚 考研者视角","s":"面试与实战高频：","c":null}]}],"exams":[{"kind":"choice","q":"广播后的 shape 推导","stem":"给定 A.shape == (2, 1, 3)、B.shape == (4, 3)，执行 C = A + B，C.shape 是多少？","opts":[{"k":"A","t":"(2, 1, 3)"},{"k":"B","t":"(2, 4, 1)"},{"k":"C","t":"(2, 4, 3)"},{"k":"D","t":"抛出 ValueError，两者形状不兼容"}],"ans":"C","why":"广播对齐方向是「从最后一个维度向前」，这是本章第一性规则。"},{"kind":"fix_error","q":"聚合后广播失败的归一化","stem":"x 是 (N, D) 的特征矩阵（每行一个样本），想对每一列去中心化，有人写成 x - x.mean(axis=0) 报错。请指出问题并给出正确写法（至少两种）。","opts":[],"ans":"# 错误：x.mean(axis=0).shape == (D,)，与 (N, D) 尾维对齐 (D==D) 其实可广播， # 但若写成 axis=1 得到 (N,)，与 (N,D) 尾维 D vs N 不匹配 → ValueError # 正确写法 1：聚合时保持维度 x_centered = x - x.mean(…","why":"keepdims 是避免手工升维出错的标准手段。"},{"kind":"output","q":"新旧随机数 API 的可复现性","stem":"执行下面代码，分别输出什么？为什么第二段不是「接着第一段之后的流」？ python import numpy as np print(np.random.default_rng(0).standard_normal(1)) print(np.random.default_rng(0).standard_normal(1)) r = np.random.default_rng(0) print(r.…","opts":[],"ans":"# 输出示意（具体数值取决于版本，重点是：1、2 相同，3、4 不同） # [0.12...] # [0.12...] # [0.12...] # [-1.04...]","why":"区分「重置随机流」与「延续随机流」是随机数工程的第一课。"},{"kind":"coding","q":"重塑矩阵（reshape 与 C 顺序）","stem":"给定矩阵与目标行列数，若元素总数匹配则重塑，否则原样返回。用 NumPy 的 reshape 语义实现（详见题链，仅存链接不搬运题面）。","opts":[],"ans":"def matrix_reshape(mat, r, c): import numpy as np a = np.array(mat) if a.size != r c: return mat return a.reshape(r, c).tolist() # 按 C order（行优先）填充","why":"理解 reshape 的填充顺序（C vs F）是向量化思维的进阶起点。"},{"kind":"coding","q":"矩阵乘法（向量化与 einsum）","stem":"实现两个矩阵相乘，要求向量化完成（禁止显式三重循环），并分别用 np.dot / @ 与 np.einsum 给出两种写法（详见题链，仅存链接不搬运题面）。","opts":[],"ans":"def matmul_vec(A, B): import numpy as np A = np.asarray(A, dtype=float); B = np.asarray(B, dtype=float) return A @ B # 写法一：@（走 BLAS） # return np.einsum('ij,jk->…","why":"区分「语义上矩阵乘」与「工程最优实现」——金融/算法岗常考向量化改写。"},{"kind":"choice","q":"dtype 溢出与精度","stem":"在 NumPy 中（继承 C 语义），下列说法正确的是？","opts":[{"k":"A","t":"np.int8(127) + np.int8(1) 会抛出 OverflowError"},{"k":"B","t":"np.uint8(255) + np.int8(1) 结果是 0"},{"k":"C","t":"对 1e7 个 float32 求和，误差通常可忽略（< 1e-6）"},{"k":"D","t":"np.float64(1.7e308) 10 结果是 nan"}],"ans":"B","why":"dtype 精度与溢出是数值计算岗的高频隐蔽坑。"}],"works":[{"h":"以为 broadcast_to 后「占用大内存」","d":"broadcast_to 是零拷贝视图（被拉伸维 stride=0），物理内存仍是原数组大小；真正爆炸发生在 np.array(big) / np.tile 物化时。判断：big.strides[0]==0 为 True 即零拷贝；要省内存就不要把广播结果 .copy()，让后续算子直接吃 view。"},{"h":"(3,) 想按列广播到 (3,4) 却报错","d":"广播从尾维对齐，(3,) 尾维 3 与 (3,4) 尾维 4 不相容。正确写法是在尾部插维：v[:, None]（得 (3,1)）或 v.reshape(3,1)，再参与 (3,4) 运算。"},{"h":"用 np.random.seed 给 default_rng 设种子","d":"两者是独立机制，旧式全局 seed 不影响新式 Generator。正确写法：rng = np.random.default_rng(seed)，并把 rng 作为显式依赖传入，禁止依赖全局随机态（多线程会互相踩踏）。"},{"h":"以为 default_rng(same_seed) 两次调用会接着上次的流","d":"每次 default_rng(seed) 都从 seed 重建初始状态，所以连续两次 default_rng(0).random() 得到相同值。要延续随机流就复用同一个 rng 实例，不要反复重建。"},{"h":"as_strided 造出重叠视图后写数据，隔山打牛","d":"手写 as_strided 可让多个「逻辑元素」指向同一物理地址；写 view[0,2]=x 会同时改掉 view[1,0]。正确做法：优先用官方封装 sliding_window_view；必须手写时只读不写，或确认无重叠。"},{"h":"a.T 后误以为数据被搬动 / 以为它连续","d":"转置只交换 strides，是 O(1) 视图、不搬数据，但结果失去 C 连续性（a.T.flags['C_CONTIGUOUS']==False）。后续需要连续输入的算子会偷偷拷贝；性能敏感处用 np.ascontiguousarray(a.T) 提前规整。"},{"h":"按列遍历 C 顺序大数组导致 cache 命中率骤降","d":"对 C 数组 for j in range(cols): A[:,j] 是跨整行跳跃访问，每次几乎 cache miss。正确写法：按行遍历，或转 F order，或一次性 A.sum(axis=0)（ufunc 内部已针对布局优化）。"},{"h":"float32 累加大规模数据却不检查误差","d":"float32 仅约 7 位有效数字，对 10^7 个数求和误差可达 1 量级。正确写法：统计量 / 金额 / 计数统一用 float64 累加，性能瓶颈确认后再考虑降位。"}],"asks":[{"q":"广播（broadcasting）具体是怎么实现的？为什么它「零拷贝」但有时又会「内存爆炸」？","a":"广播从尾维逐维对齐，两维相容当且仅当：相等 / 其一为 1 / 其一不存在。 实现：NumPy 不复制数据，而是把「被拉伸维」的 stride 设为 0。np.broadcast_to(np.arange(4), (3,4)).strides == (0, 8)——沿第 0 维移动地址不变，永远读同一元素。因此广播是 O(1) 的视图操作，额外内存为 0。 内存爆炸：一旦把广播结果物化（np.ar…","fu":["broadcast_to 返回的数组能写吗？为什么？","np.tile 和 np.broadcast_to 在实现与内存上的本质区别是什么？"],"tag":"字节跳动/阿里巴巴"},{"q":"NumPy 的新随机数 API（default_rng / Generator）和旧式 np.random.seed 有什么区别？生产环境为什么推荐前者？","a":"旧式：np.random.seed/rand/randn 操作一个进程级全局 RandomState，任何地方调用都推进同一条流——多线程 / 多模块各自 reseed 会互相踩踏，CI 里一处改种子另一处随机测试就「玄学」失败。 新式：np.random.default_rng(seed) 返回独立的 Generator 实例，底层是 PCG64 等 BitGenerator。状态封进对象、互不…","fu":["default_rng(seed) 连续两次调用得到的值是相同还是延续？为什么？","PCG64 相比 Mersenne Twister 的优势在哪里？"],"tag":"腾讯/美团"},{"q":"为什么向量化比 Python 循环快两个数量级？在什么情况下向量化反而更慢？","a":"加速来自三重叠加：① 解释器开销消失——循环体下沉到 C 层一次 ufunc 调用，避免 N 次 Python 层往返与逐元素类型分派；② cache 局部性——连续同构内存让预取器提前加载后续 cache line，跳跃访问几乎必 miss；③ SIMD——连续布局使编译器发 AVX2/AVX-512，一条指令并行处理 4~8 个 float64。N=2e6 点积：循环 ~1000ms、推导 ~…","fu":["向量化是降低了时间复杂度还是只降低常数？","如何避免链式运算的中间数组撑爆内存？"],"tag":"字节跳动/百度"},{"q":"np.einsum 是什么？它和直接用 @ / np.tensordot 比有什么优劣？什么情况下会慢？","a":"einsum 用爱因斯坦求和约定的下标标记描述任意张量收缩：重复下标在该维求缩并、只出现一次的下标保留为输出维。它把矩阵乘 / 转置 / 迹 / 批量矩阵乘统一成一套记号，且无需显式中间数组。 优劣：可读性与表达力强、无中间数组；但默认 einsum 不一定最快，小矩阵与 @ 相近、大矩阵 @ 走 BLAS 通常更快。 会慢的情况：复杂收缩若不指定 optimize=True，可能退化成低效实现…","fu":["用 einsum 表示矩阵乘法、求迹、批量矩阵乘的下标分别是什么？","optimize=True 背后做了什么（类比什么算法）？"],"tag":"量化私募/字节跳动"}]},{"id":"data-ch03","subj":"data","title":"Pandas 基础：Series 与 DataFrame","summary":"Series/DataFrame 的索引语义与自动对齐（这是与 NumPy 最大的差异）；读写 CSV/Excel（编码、分隔符、chunksize 分块）；iloc（位置）vs loc（标签）vs 直接下标的行为差异；缺失值处理（NaN/…","concepts":[{"id":"data-ch03/01-series-dataframe-and-alignment","file":"01-series-dataframe-and-alignment.md","title":"Series、DataFrame 与「自动对齐」","kind":"stack","secs":[{"h":"1. 两个核心数据结构","s":"它的组成是三个部分，而不是两个：","c":{"lang":"python","code":"import pandas as pd\ns = pd.Series([10, 20, 30], index=[\"a\", \"b\", \"c\"])"}},{"h":"2. 自动对齐：Pandas 的灵魂","s":"结果是：","c":{"lang":"python","code":"a = pd.Series([1, 2, 3], index=[\"x\", \"y\", \"z\"])\nb = pd.Series([10, 20, 30], index=[\"z\", \"y\", \"x\"])\n\nprint(a + b)"}},{"h":"3. 三视角：索引与对齐","s":"是「标签对齐」在重复标签下的必然结果。","c":{"lang":"python","code":"# ① 先看两边索引是否一致\nprint(a.index.equals(b.index))       # 快速判断\nprint(a.index.difference(b.index))   # 只在 a 里的标签\nprint(b.index.difference(a.index))   # 只在 b 里的标签\nprint(a.index.has_duplicates, b.index.has_duplicates)   # 有没有重复标签！"}},{"h":"4. 常用构造与查看","s":"所以 df[\"price\"] 会报 KeyError: 'price'，必须显式传 columns=。","c":null}]},{"id":"data-ch03/02-io-csv-excel-chunking","file":"02-io-csv-excel-chunking.md","title":"读写 CSV / Excel 与分块处理","kind":"stack","secs":[{"h":"1. read_csv 的关键参数","s":"这些假设在真实数据里经常不成立，于是需要逐项覆盖：","c":{"lang":"python","code":"import pandas as pd\ndf = pd.read_csv(\"data.csv\")"}},{"h":"2. Excel 的读与写","s":"尤其是 ID 类字段，务必 dtype=str。","c":{"lang":"python","code":"df = pd.read_excel(\"book.xlsx\", sheet_name=\"Sheet1\", dtype={\"id\": str})\nwith pd.ExcelWriter(\"out.xlsx\", engine=\"openpyxl\") as w:\n    df.to_excel(w, sheet_name=\"cleaned\", index=False)\n    summary.to_excel(w, sheet_name=\"summary\", index=False)"}},{"h":"3. 分块读：文件比内存大怎么办","s":"chunksize 让 read_csv 返回一个迭代器，每次产出一个不超过 N 行的 DataFrame：","c":{"lang":"python","code":"total = 0\nfor chunk in pd.read_csv(\"huge.csv\", chunksize=100_000, usecols=[\"amount\"]):\n    total += chunk[\"amount\"].sum()\nprint(total)"}},{"h":"4. 三视角：IO 与分块","s":"经验起点是让单块占几十 MB 内存，用 df.memory_usage(deep=True).sum() 量一下再调。","c":{"lang":"python","code":"# 1. 先看原始字节，确认编码与分隔符\n#    head -c 200 data.csv | xxd | head      （命令行）\n# 2. 读前 5 行看结构\ndf = pd.read_csv(\"data.csv\", nrows=5)\nprint(df.dtypes, df.shape)\n# 3. 再全量读，仍然显式给 dtype"}}]},{"id":"data-ch03/03-iloc-loc-and-chained-assignment","file":"03-iloc-loc-and-chained-assignment.md","title":"索引器：iloc、loc 与链式赋值","kind":"flow","secs":[{"h":"1. 三种取法的行为差异","s":"对下面这张表：","c":{"lang":"python","code":"df = pd.DataFrame({\"v\": [10, 20, 30, 40]}, index=[10, 20, 30, 40])"}},{"h":"2. iloc 与 loc 的完整能力","s":"多条件必须用 & / | / ~，并且每个条件都要加括号：","c":{"lang":"python","code":"df.iloc[0, 1]          # 位置：第 0 行第 1 列\ndf.iloc[0:3, 0:2]      # 位置切片（左闭右开）\ndf.iloc[:, -1]         # 最后一列\ndf.iloc[[0, 2, 4]]     # 花式索引：离散的行号列表\n\ndf.loc[\"r1\", \"col\"]    # 标签：行标签、列名\ndf.loc[\"r1\":\"r3\", [\"a\", \"b\"]]     # 标签切片 + 列名列表\ndf.loc[df[\"v\"] > 20]   # 布尔索引（常用！）\ndf.loc[:, \"a\":\"c\"]     # 列也支持标签切片（闭区间）"}},{"h":"3. 链式赋值与 SettingWithCopyWarning","s":"Pandas 会警告：A value is trying to be set on a copy of a slice from a DataFrame。","c":{"lang":"python","code":"subset = df[df[\"v\"] > 20]        # 这一步是「视图」还是「副本」？Pandas 不保证\nsubset[\"w\"] = 0                  # ❌ 可能只改了临时对象，df 完全没变"}},{"h":"4. 三视角：索引器与赋值语义","s":"1. KeyError: 0 —— 你在用 loc 但表的是默认整数索引的标签吗？","c":null}]},{"id":"data-ch03/04-missing-values-dtype-and-memory","file":"04-missing-values-dtype-and-memory.md","title":"缺失值、dtype 与内存优化","kind":"stack","secs":[{"h":"1. 缺失值的三种标记","s":"「除以总行数」？Pandas 默认前者。若要后者，得自己算 sum() / len(s)。","c":{"lang":"python","code":"np.nan == np.nan        # False\ndf[df[\"v\"] == np.nan]   # 永远返回空表！\ndf[df[\"v\"].isna()]      # ✅ 正确做法"}},{"h":"2. 检测与处理缺失","s":"1. 缺失是「随机」还是「有信息」？ 若「没填手机号」的用户恰好是特定人群，","c":{"lang":"python","code":"df.isna().sum()                        # 每列缺失数量\ndf.isna().mean()                       # 每列缺失比例（更直观）\ndf.isna().sum(axis=1)                  # 每行缺失数量\ndf.isna().any()                        # 哪些列有缺失"}},{"h":"3. dtype 与内存","s":"完全低估了真实占用——字符串内容存在堆上，必须 deep=True 才能量准。","c":{"lang":"python","code":"df.info(memory_usage=\"deep\")                      # 各列占用明细\ndf.memory_usage(deep=True).sum() / 1024**2        # 总内存（MB）"}},{"h":"4. 三视角：缺失值与内存","s":"盲目 astype(\"int8\") 会静默溢出（int8 超出 127 会变成负数），","c":{"lang":"text","code":"df.memory_usage(deep=True).sort_values(ascending=False)   # 先排序，看大户\n│\n├─ 最大的是 object 列？\n│   ├─ nunique()/len() < 0.5 → astype(\"category\")   ← 收益最大\n│   └─ 基数很高（如 ID）      → 考虑 drop 或哈希编码，category 会变慢\n│\n├─ 最大的是 int64 列？\n│   └─ to_numeric(downcast=\"integer\")  ← 收益 = 原字节/新字节\n│\n…"}}]}],"exams":[{"kind":"choice","q":"自动对齐后的结果与 dtype","stem":"执行下面的代码，(a + b) 的结果是什么？ python a = pd.Series([1, 2], index=[\"x\", \"y\"]) b = pd.Series([10], index=[\"y\"]) print((a + b).to_dict()) print((a + b).dtype)","opts":[{"k":"A","t":"{'x': 1, 'y': 12}，dtype 为 int64"},{"k":"B","t":"{'x': nan, 'y': 12.0}，dtype 为 float64"},{"k":"C","t":"{'y': 12}，dtype 为 int64（只保留交集）"},{"k":"D","t":"抛 ValueError，因为索引长度不一致"}],"ans":"B","why":"Pandas 的加法按标签对齐并取并集：标签 x 只在 a 里有值，b 里没有，因此结果为 NaN；y 两边都有，得 1 + 10 = 12。由于出现了 NaN，而 int64 无法表示缺失，整列被提升为 float64，12 显示为 12.0。C 是 join='inner' 的语义，不是默认行为。"},{"kind":"fix_error","q":"修复链式赋值导致「改了没生效」","stem":"下面的代码想「把 score 大于 60 的行的 passed 列设为 True」，但运行后 df 一点没变，还给出了 SettingWithCopyWarning。请指出原因并给出两种正确写法。 python df = pd.DataFrame({\"score\": [50, 70, 90]}) df[df[\"score\"] > 60][\"passed\"] = True print(df) # 没…","opts":[],"ans":"","why":"考点是链式赋值的语义不确定性与 CoW 带来的行为变化（3.0 起链式赋值不再能改原表）。"},{"kind":"output","q":"loc 与 iloc 的切片端点","stem":"对 s = pd.Series([1, 2, 3, 4, 5], index=list(\"abcde\"))， python print(s.loc[\"b\":\"d\"].tolist()) print(s.iloc[1:3].tolist()) 两行分别输出什么？","opts":[],"ans":"","why":"这是 Pandas 最反直觉的一处设计，也是「多取一行」这类静默错误的常见来源。"},{"kind":"output","q":"缺失值处理对统计量的影响","stem":"python import pandas as pd, numpy as np s = pd.Series([10.0, np.nan, 20.0, np.nan, 30.0]) print(s.mean(), s.count(), len(s)) (1) 输出什么？(2) 如果改成 s.fillna(s.mean()) 后再算 std()，与只用非空值算 std() 相比会偏大还是偏小？为什么？","opts":[],"ans":"","why":"考点是「聚合默认跳过缺失」与「填充会压缩方差」这两件容易被忽略但影响结论的事。"},{"kind":"coding","q":"修改列（LeetCode 2884 · Modify Columns）","stem":"见题目链接。这是一道 Pandas 专项编程题，要求对 DataFrame 的某一列做整体变换（乘以常数），正好练习整列向量化赋值的写法。","opts":[],"ans":"","why":"把本章的「列操作 + 避免链式赋值」落到代码上。LeetCode 题面正文不搬运，仅存链接。"},{"kind":"coding","q":"连接数据（LeetCode 2888 · Reshape Data: Concatenate）","stem":"见题目链接。要求把两个结构相同的 DataFrame 纵向堆叠，练习 concat 的轴参数与索引处理（ignore_index）——这正是概念 01「索引对齐」的直接应用场景。","opts":[],"ans":"","why":"考点是 concat 的轴语义与 ignore_index 的必要性，直接呼应本章的索引对齐主线。LeetCode 题面正文不搬运，仅存链接。"}],"works":[{"h":"用 df[df[\"v\"] == np.nan] 找缺失行","d":"NaN != NaN 恒为真，这个表达式永远返回空表， 而且不报错。正确写法是 df[df[\"v\"].isna()]（isnull() 是别名）。 同理，df[\"v\"].fillna(...) 之后想校验是否还有缺失，要用 isna().any() 而不是 == np.nan。"},{"h":"忘了 Pandas 是按索引对齐的","d":"两个从数据库读出的表直接相减， 若索引是行号而两批数据的行序不同，结果会全是 NaN。 修复：先 set_index(\"业务主键\") 再做运算，或先 reset_index(drop=True) 并确认行序一致。"},{"h":"索引有重复标签时对齐会「行数膨胀」","d":"a + b 若 a 的索引有重复， 结果是笛卡尔积（x 出现 2 次 × 另一边 3 次 = 6 行），看起来像 bug 其实是对齐的必然结果。 排查：df.index.has_duplicates；修复：先去重再运算。"},{"h":"把 loc 的切片当成左闭右开","d":"s.loc[\"b\":\"d\"] 取的是 b、c、d 三行， 而 s.iloc[1:3] 取的是 b、c 两行。 loc 是闭区间（因为标签空间没有「下一个」的自然定义）。 混用会导致「多取一行」这类静默错误，尤其在 df.loc[0:3] 时最容易被忽略。"},{"h":"用链式赋值修改数据","d":"df[df[\"v\"] > 20][\"w\"] = 0 会触发 SettingWithCopyWarning，且修改可能根本没生效（或反而改了原表）。 两种正确修法：subset = df[cond].copy() 后再改，或 df.loc[df[\"v\"] > 20, \"w\"] = 0 一步到位。 Pandas 3.0 起 CoW 默认开…"},{"h":"用 df.colname 代替 df[\"colname\"]","d":"列名叫 count、sum、mean、index、 size、values 时，属性访问会返回方法对象而不是列， 后续 df.count + 1 报出莫名其妙的错误。永远用 df[\"colname\"]。"},{"h":"整数 ID 读进来变成 1001.0","d":"两个原因： (a) 该列含缺失值，int64 装不下 NaN，Pandas 升级为 float64； (b) CSV 解析把纯数字列推断成了数值型。 修复：读入时 dtype={\"id\": str}；需要「整数 + 缺失」时用 Int64（大写 I）。"},{"h":"中文 CSV 读进来乱码或第一列名带 \\ufeff","d":"前者是编码不对（试 gb18030），后者是 UTF-8 BOM（Excel 另存为的产物）， 用 encoding=\"utf-8-sig\" 解决。写出时同理： to_csv(..., encoding=\"utf-8-sig\") 才能让 Excel 正常打开中文。"}],"asks":[{"q":"Pandas 和 NumPy 最本质的区别是什么？","a":"一句话：Pandas 引入了「索引」，于是运算从「按位置」变成了「按标签对齐」。 具体展开成三个层次： ① 数据结构 - NumPy 是同质稠密数组：所有元素同一 dtype，用整数位置索引； - Pandas 是列导向的异构表：Series = values + index + name， DataFrame = 共享行索引的一组 Series，每列可以有自己的 dtype。 ② 运算语义 py…","fu":["两个索引相同的 Series 相加，为什么结果还是 float64？","怎么让缺失不产生 NaN？（add(b, fill_value=0)）"],"tag":"数据分析岗/算法工程"},{"q":"loc、iloc 和直接下标有什么区别？链式赋值为什么危险？","a":"两种坐标（位置 / 标签）→ 两套索引器。 | 写法 | 语义 | 切片端点 | |---|---|---| | df.iloc[1:3] | 位置 | 左闭右开（与 Python 一致） | | df.loc[\"b\":\"d\"] | 标签 | 两端都包含（闭区间） | | df[0:2] | 整数切片走位置；字符串取列 | 左闭右开 | 为什么 loc 是闭区间：标签空间未必连续、未必有序， 「开…","fu":["为什么不要用 df.colname 取列？（列名与方法名冲突时会取到方法）","多条件掩码为什么要加括号？（& 与 > 的优先级）"],"tag":"数据开发/BI 工程"},{"q":"数据里的缺失值你会怎么处理？","a":"先体检，再决定，绝不直接 dropna。 第 1 步：体检 python df.isna().sum() # 每列缺失数 df.isna().mean() # 每列缺失比例 df.isna().sum(axis=1) # 每行缺失数 第 2 步：判断缺失机制（这一步最常被跳过，但决定方法是否有偏） | 机制 | 含义 | 后果 | |---|---|---| | MCAR 完全随机 | 缺失与任何…","fu":["为什么整数列的 NaN 会让 dtype 变成 float64？（int64 装不下 NaN）","怎么保住整数类型？（Int64 Nullable dtype）"],"tag":"数据分析岗/风控建模"},{"q":"一个 DataFrame 占了几个 G，你会怎么优化内存？","a":"核心思路：先定位大户，再分类型处理。 第 1 步：量准 python df.memory_usage(deep=True).sort_values(ascending=False) df.info(memory_usage=\"deep\") ⚠️ 必须加 deep=True：否则 object 列只算 8 字节指针， 完全低估真实占用（字符串内容在堆上）。 第 2 步：按列的 dtype 分别处理…","fu":["为什么 category 对 ID 列反而更费内存？","不加 deep=True 会低估多少？（object 列只算 8 字节指针）"],"tag":"数据开发/大数据"}]},{"id":"data-ch04","subj":"data","title":"Pandas 进阶：分组聚合、合并与时间序列","summary":"groupby 的 split-apply-combine 心智模型；agg/transform/apply 的差异与选择；多表合并（merge/join/concat）与 SQL JOIN 的对照（inner/left/right/out…","concepts":[{"id":"data-ch04/01-groupby-split-apply-combine","file":"01-groupby-split-apply-combine.md","title":"groupby：split-apply-combine 与四种聚合器","kind":"flow","secs":[{"h":"1. 心智模型：split → apply → combine","s":"groupby 不是「一个函数」，而是一套三步流水线：","c":{"lang":"text","code":"   ┌── split ──┐     ┌── apply ──┐     ┌── combine ──┐\n   │ 按 key 把  │     │ 对每个子集 │     │ 把子结果按  │\n   │ 行切成若干组│ ──▶ │ 施加一个函数│ ──▶ │ 组标签拼回  │\n   └───────────┘     └───────────┘     └─────────────┘"}},{"h":"2. 四种聚合器：返回形状决定用途","s":"这是本章最容易记混、也最常考的一组对比：","c":{"lang":"python","code":"df[\"city_mean\"] = df.groupby(\"city\")[\"sales\"].transform(\"mean\")\n# transform 返回和 df 一样长的 Series，可以直接赋值成新列"}},{"h":"3. 分组键的六种形态","s":"groupby 的第一参数远不止「列名」：","c":{"lang":"python","code":"df.groupby(\"city\")                       # ① 列名\ndf.groupby([\"city\", \"month\"])            # ② 多列（结果是 MultiIndex）\ndf.groupby(df[\"sales\"] > 15)             # ③ 布尔 Series（二分）\ndf.groupby(lambda i: i % 2)              # ④ 按索引位置分奇偶\ndf.groupby(df[\"city\"].str.upper())       # ⑤ 任意 Series（可与 df 无关，需长度相同）\ndf.groupby(level=\"city\")                 # ⑥ 按索引层级（index 已经 set_index 过时）"}},{"h":"4. 命名聚合（Named Aggregation）：一次出多指标","s":"旧写法用字典，新写法推荐用 numpy 风格的关键字：","c":{"lang":"python","code":"out = df.groupby(\"city\").agg(\n    销售额=(\"sales\", \"sum\"),\n    订单数=(\"sales\", \"size\"),\n    最大值=(\"sales\", \"max\"),\n)"}},{"h":"5. 三视角：分组语义","s":"1. 结果要不要回到原表？ 要 → transform；不要 → agg。","c":{"lang":"text","code":"① 形状不对？        -> 用了哪个聚合器（agg/transform/apply）\n② 行数变少？        -> key 里有 NaN 被 dropna 丢了 / 组被 filter 掉了\n③ 列名变成元组？    -> 多函数聚合产生了 MultiIndex 列，用命名聚合拍平\n④ 内存爆了？        -> Categorical 分组没加 observed=True"}},{"h":"6. 常见陷阱速查","s":"","c":null}]},{"id":"data-ch04/02-merge-join-concat","file":"02-merge-join-concat.md","title":"多表连接：merge / join / concat 与笛卡尔积陷阱","kind":"compare","secs":[{"h":"1. 三者的定位：一句话区分","s":"若 right 的键在列里，必须写 left.join(right.set_index(\"id\"), on=\"id\") 或","c":{"lang":"python","code":"pd.merge(left, right, on=\"id\", how=\"left\")   # 按列 id 连接\nleft.join(right, how=\"left\")                 # 默认按索引连接（等价于 left_on=index）\npd.concat([df1, df2], axis=0, ignore_index=True)   # 上下堆叠"}},{"h":"2. 四种连接语义与 SQL 对照","s":"设 how 参数：","c":{"lang":"python","code":"l = pd.DataFrame({\"id\": [1, 2, 3], \"a\": [\"x\", \"y\", \"z\"]})\nr = pd.DataFrame({\"id\": [2, 3, 4], \"b\": [20, 30, 40]})\n\nprint(pd.merge(l, r, on=\"id\", how=\"inner\").shape)   # (2, 3)  只留 2、3\nprint(pd.merge(l, r, on=\"id\", how=\"left\").shape)    # (3, 3)  保留 1，b 为 NaN\nprint(pd.merge(l, r, on=\"id\", how=\"outer\").shape)   # (4, 3)  1/2/3/4 都在"}},{"h":"3. 多对多：行数膨胀（本章最重要的一节）","s":"计算方式：键 1 在左 2 行、在右 2 行 → 产生 $2 \\times 2 = 4$ 行；","c":{"lang":"python","code":"l = pd.DataFrame({\"id\": [1, 1, 2], \"a\": [\"x\", \"y\", \"z\"]})   # id=1 出现 2 次\nr = pd.DataFrame({\"id\": [1, 1, 3], \"b\": [10, 20, 30]})      # id=1 出现 2 次\n\nm = pd.merge(l, r, on=\"id\", how=\"inner\")\nprint(m.shape)     # (5, 3) —— 左 3 行 + 右 3 行，结果却是 5 行！"}},{"h":"4. 列名冲突：suffixes","s":"两表有同名列（非键）时，结果列会加后缀：","c":{"lang":"python","code":"pd.merge(l, r, on=\"id\", suffixes=(\"_左\", \"_右\"))"}},{"h":"5. concat 的两个坑","s":"坑 1：axis=0 是按列名对齐的，不是按位置。两表列名不一致时，","c":{"lang":"python","code":"pd.concat([df1, df2], axis=0)                       # 上下堆叠，默认按列名对齐！\npd.concat([df1, df2], axis=0, ignore_index=True)    # 重建索引\npd.concat([df1, df2], axis=1)                       # 左右拼接，按索引对齐"}},{"h":"6. 三视角：关系代数","s":"1. left[key].nunique() == len(left) ？","c":{"lang":"text","code":"要按列连？  ── 是 ──▶ merge(on=..., how=...)\n            └─ 否 ─▶ 要按索引连？ ── 是 ──▶ join(how=...)\n                                   └─ 否 ─▶ 只是堆叠？ ──▶ concat(axis=...)"}},{"h":"7. 陷阱速查","s":"","c":null}]},{"id":"data-ch04/03-time-series-resample-rolling","file":"03-time-series-resample-rolling.md","title":"时间序列：DatetimeIndex、resample 与 rolling","kind":"flow","secs":[{"h":"1. 先把「时间」变成对的类型","s":"时间序列的一切麻烦，八成源于时间列还是字符串。","c":{"lang":"python","code":"import pandas as pd\n\ndf = pd.read_csv(\"sales.csv\", parse_dates=[\"ts\"])     # ① 读入时就解析\ndf[\"ts\"] = pd.to_datetime(df[\"ts\"], errors=\"coerce\")  # ② 事后转换（脏值变 NaT）\ndf[\"ts\"] = pd.to_datetime(df[\"ts\"], format=\"%Y-%m-%d %H:%M:%S\")  # ③ 指定格式（快很多）"}},{"h":"2. DatetimeIndex 的切片能力","s":"凡是接手别人的时间数据，第一件事就是","c":{"lang":"python","code":"df = df.set_index(\"ts\").sort_index()     # 排序！很多时间操作要求单调\n\nprint(df.loc[\"2026-01\"])                  # 整个 1 月\nprint(df.loc[\"2026-01\":\"2026-03\"])        # 区间（含两端）\nprint(df.loc[\"2026-01-05\"])               # 某一天"}},{"h":"3. resample：时间维度上的 groupby","s":"resample 的心智模型就是「把时间当分组键的 groupby」：","c":{"lang":"python","code":"df.resample(\"ME\")[\"amount\"].sum()      # 按月求和\ndf.resample(\"W\")[\"amount\"].mean()     # 按周平均\ndf.resample(\"QE\")[\"amount\"].max()      # 按季度最大"}},{"h":"4. rolling / expanding / ewm：三种窗口","s":"要拿到带值的首部用 min_periods=1：","c":{"lang":"python","code":"df[\"ma7\"]  = df[\"amount\"].rolling(7).mean()        # 固定窗口（最近 7 天）\ndf[\"cum\"]  = df[\"amount\"].expanding().sum()        # 扩张窗口（从开始至今）\ndf[\"ewma\"] = df[\"amount\"].ewm(span=7).mean()       # 指数加权（越近权重越大）"}},{"h":"5. 时间运算：shift / diff / pct_change / 同比","s":"shift 是「同比/环比」的全部秘密：同一条折线，往后挪 12 个月再相除，","c":{"lang":"python","code":"df[\"prev\"]        = df[\"amount\"].shift(1)          # 上一期（首行为 NaN）\ndf[\"delta\"]       = df[\"amount\"].diff(1)           # 差分\ndf[\"growth\"]      = df[\"amount\"].pct_change()      # 环比增长率\ndf[\"yoy\"]         = df[\"amount\"].pct_change(12)    # 同比（月度数据 lag 12）"}},{"h":"6. 时区：能不用就不用，用了就要统一","s":"1. 存储一律 UTC，展示才转本地。混用本地时区做聚合，","c":{"lang":"python","code":"s = pd.to_datetime([\"2026-01-01 08:00\"]).tz_localize(\"Asia/Shanghai\")   # 挂本地时区\ns.tz_convert(\"UTC\")                                                     # 转 UTC\ndf.tz_localize(None)                                                    # 去掉时区（回到 naive）"}},{"h":"7. 三视角：时间索引","s":"报表上会显示成「断崖式下跌」。习惯做法是丢掉最后一个不完整周期，","c":{"lang":"text","code":"① df.dtypes 里 ts 是 datetime64 吗？   否 -> 先 parse_dates / to_datetime\n② index 单调递增吗？                   否 -> sort_index()（rolling 会错！）\n③ 频率别名用对了吗（ME vs MS）？         错 -> 标签整体错一个月，数字却不报警\n④ 缺口怎么处理？                        -> resample 会为「没有数据的区间」补 NaN，\n                                          不要盲目 fillna(0)（0 与「没有」语义不同）\n⑤ 时区统一了吗？                        -> 存储 UTC，展示转本地"}},{"h":"8. 陷阱速查","s":"","c":null}]},{"id":"data-ch04/04-pivot-and-performance","file":"04-pivot-and-performance.md","title":"透视表、重塑与性能：apply 到底慢在哪","kind":"flow","secs":[{"h":"1. pivot_table：带默认聚合的 groupby","s":"等价于「groupby([\"city\",\"month\"]) 之后再 unstack()」：","c":{"lang":"python","code":"df.pivot_table(index=\"city\", columns=\"month\", values=\"sales\",\n               aggfunc=\"sum\", fill_value=0)"}},{"h":"2. 重塑：wide ↔ long","s":"一句话：能保证唯一就用 pivot（更快、更严格），否则用 pivot_table。","c":{"lang":"python","code":"wide = long.pivot(index=\"date\", columns=\"item\", values=\"qty\")   # long → wide\nlong = wide.stack().rename(\"qty\").reset_index()                 # wide → long\nlong = df.melt(id_vars=[\"date\"], var_name=\"item\", value_name=\"qty\")   # 更通用"}},{"h":"3. query / eval：让表达式跑得更快","s":"query 的优点有三层：","c":{"lang":"python","code":"df.query(\"amount > 100 and city == 'BJ'\")\ndf.eval(\"total = price * qty\", inplace=False)"}},{"h":"4. apply vs 向量化：先量化，再优化","s":"应该用可复现的判据来验证：","c":{"lang":"python","code":"def has_promo(text):            # 逐行字符串判断\n    return \"PROMO\" in text\n\n# 写法 A：apply（Python 层逐行调用）\nout_a = df[\"note\"].apply(has_promo)\n\n# 写法 B：向量化（C 层批处理）\nout_b = df[\"note\"].str.contains(\"PROMO\", regex=False, na=False)\n\n…"}},{"h":"5. 三视角：性能工程","s":"1. 先 astype 再计算：category/int32 的 join 与 groupby 显著快于 object；","c":{"lang":"text","code":"① 先测量：这段代码占总耗时多少？（不要优化不到 5% 的路径）\n② 找瓶颈：是 IO（read_csv）、是 apply、还是 merge 的键 dtype？\n③ 换实现：向量化 > 内置聚合 > apply\n④ 再测量：确认真的变快了，且结果**逐元素一致**"}},{"h":"6. 陷阱速查","s":"","c":null}]},{"id":"data-ch04/05-edge-cases-perf","file":"05-edge-cases-perf.md","title":"data-ch04 · 边界情形与性能陷阱","kind":"flow","secs":[{"h":"1. 本节定位","s":"前面的例子都是「干净数据」。真实数据有缺失、有重复键、有超长序列——这些才是分组/合并/重采样真正出错的地方。","c":{"lang":"python","code":"# 错误：分组键进了索引，merge 时 on=\"k\" 找不到\ng = df.groupby(\"k\")[\"v\"].sum()\ndf.merge(g, on=\"k\")          # KeyError\n\n# 正确：把键拉回列\ng = df.groupby(\"k\", as_index=False)[\"v\"].sum()\ndf.merge(g, on=\"k\")"}}]}],"exams":[{"kind":"choice","q":"agg 与 transform 的返回形状","stem":"要把「每个城市销售额的组内均值」加成一列（与 df 行数相同），下面哪个写法是正确的？","opts":[{"k":"A","t":"df[\"m\"] = df.groupby(\"city\")[\"sales\"].agg(\"mean\")"},{"k":"B","t":"df[\"m\"] = df.groupby(\"city\")[\"sales\"].transform(\"mean\")"},{"k":"C","t":"df[\"m\"] = df.groupby(\"city\")[\"sales\"].apply(\"mean\")"},{"k":"D","t":"df[\"m\"] = df.groupby(\"city\")[\"sales\"].filter(\"mean\")"}],"ans":"B","why":"transform 的契约是「输入 n 行、输出 n 行」，第 i 行的值由它所属的组决定，因此返回与 df 同长、索引一致的 Series，可以直接赋值成新列。agg 每组只返回一行（长度 = 组数），赋值会因长度不匹配而对不齐；apply 返回什么取决于函数（返回标量时同样不是同长序列）；filter 返回的是行的子集，语义完全不同。"},{"kind":"choice","q":"多对多合并后的行数","stem":"左表 id 取值为 [1, 1, 2]（3 行），右表 id 取值为 [1, 1, 3]（3 行）。pd.merge(left, right, on=\"id\", how=\"inner\") 的结果有多少行？","opts":[{"k":"A","t":"2 行（只保留两边都有的键 1）"},{"k":"B","t":"3 行（与左表相同）"},{"k":"C","t":"4 行（键 1 在左 2 行 × 右 2 行）"},{"k":"D","t":"9 行（3 × 3 笛卡尔积）"}],"ans":"C","why":"连接的定义是笛卡尔积再筛选：$L \\bowtie R = \\sigma_{L.k=R.k}(L \\times R)$。对每个键 $k$，它贡献 $\\text{cnt}_L(k) \\times \\text{cnt}_R(k)$ 行。键 1：$2 \\times 2 = 4$ 行；键 2 只在左、键 3 只在右，inner 下都被丢弃。所以结果是 4 行。D 项的 9 行是把「全部键…"},{"kind":"output","q":"groupby 遇到 NaN 键","stem":"下面的代码会打印什么？请说明为什么两者不同。 python import pandas as pd, numpy as np df = pd.DataFrame({\"city\": [\"BJ\", None, \"SH\"], \"v\": [1, 2, 3]}) print(df.groupby(\"city\")[\"v\"].sum().to_dict()) print(df.groupby(\"city\", d…","opts":[],"ans":"见解析","why":"第一行输出 {'BJ': 1, 'SH': 3} —— dropna 默认 True，键为 NaN 的那一行被整组丢弃（v=2 静默消失）。 第二行输出 {'BJ': 1, nan: 2, 'SH': 3} —— dropna=False 让缺失单独成一组。 这是一个不报错的静默错误，做「缺失也算一类」的统计时（如渠道归因中的「未知来源」）必须显式写 dropna=False…"},{"kind":"fix_error","q":"join 连出一堆 NaN","stem":"下面代码想按 id 列把两表左连接，但结果里 b 列全是 NaN。请指出原因并给出两种修法。 python l = pd.DataFrame({\"id\": [1, 2], \"a\": [\"x\", \"y\"]}) r = pd.DataFrame({\"id\": [1, 2], \"b\": [10, 20]}) out = l.join(r, how=\"left\", rsuffix=\"_r\")","opts":[],"ans":"见解析","why":"原因：DataFrame.join 默认按索引对齐，而两表的索引是 0, 1，id 只是一列数据。它拿左表索引 0/1 去匹配右表索引 0/1，虽然索引能对上，但 b 列的键并非 id 的对齐依据——在 id 与索引不一致的真实数据里就会大面积产生 NaN。 修法 1：把右表的键设为索引 python out = l.join(r.set_index(\"id\"), on=\"id…"},{"kind":"choice","q":"resample 的 M 与 MS","stem":"对 2026 年 1 月的日频数据，s.resample(\"M\").sum() 与 s.resample(\"MS\").sum() 的区别是什么？","opts":[{"k":"A","t":"完全一样，两个别名等价"},{"k":"B","t":"M 按月末对齐（标签是 01-31），MS 按月初对齐（标签是 01-01）"},{"k":"C","t":"M 是月度、MS 是季度，聚合区间不同"},{"k":"D","t":"MS 会多出一行，因为它包含了 1 月之前的数据"}],"ans":"B","why":"M = month end，把整月数据归到月末那一天（2026-01-31）；MS = month start，归到月初（2026-01-01）。两者的数值完全相同，只有时间标签位置不同——这正是它危险的地方：数字全对，时间标签错位，肉眼很难发现。C 项的季度别名是 Q/QS，D 项无此性质。"},{"kind":"output","q":"rolling 的前几行为什么是 NaN","stem":"s 是 10 天的日频序列。s.rolling(3).mean() 的前两个值是什么？如果希望从第一天就有值，应该怎么写？","opts":[],"ans":"前两个是 NaN；用 min_periods=1","why":"rolling(3) 要求窗口内至少有 3 个观测，因此前 2 个位置不足窗口，结果为 NaN（默认 min_periods=window）。 若希望第一个点就有值： python s.rolling(3, min_periods=1).mean() 边界口径：rolling(n) 的第 $t$ 个窗口是 $[t-n+1,\\ t]$，右端闭合、包含当前点。若需要「不含当前点」的…"},{"kind":"coding","q":"LeetCode 2891 · 方法链（Method Chaining）","stem":"用一条链式调用完成数据筛选、排序与列重命名，不引入中间变量。本题为 LeetCode 官方 Pandas 专题题，题面与数据请见链接。","opts":[],"ans":"见链接","why":"考点：把 query / sort_values / rename / reset_index 串成一条链，体现「无中间变量」的数据处理风格。 链式写法的两个工程价值： ① 步骤即文档 —— 每一步做了什么，从上到下读一遍就清楚； ② 便于插入调试 —— 用 .pipe() 可以在链中间挂一个打印函数。 常见坑：链中若出现 df[col] = ...（赋值）会打断链，应改用 .…"},{"kind":"coding","q":"LeetCode 185 · 部门工资前三高的员工","stem":"按部门分组，取出每组薪资排名前三的员工。本题考察「分组 + 组内排名」，题面与数据请见链接。","opts":[],"ans":"见链接","why":"考点：groupby + 组内排名/取前 k。两种思路： ① 向量化路线：groupby(\"dept\").apply(lambda g: g.nlargest(3, \"salary\"))； ② 全表路线：df.groupby(\"dept\")[\"salary\"].rank(method=\"dense\", ascending=False) 再筛 <= 3——更向量化、更快。 排名语…"}],"works":[{"h":"agg 当 transform 用","d":"df[\"m\"] = df.groupby(\"k\")[\"v\"].agg(\"mean\") 会因长度不匹配而失败或产生错误的索引对齐。要广播回原表必须用 transform：df[\"m\"] = df.groupby(\"k\")[\"v\"].transform(\"mean\")。 正确做法：要广播回原表用 groupby(\"k\")[\"v\"].tra…"},{"h":"groupby 默认把 NaN 键丢掉","d":"dropna 默认为 True，键为 NaN 的行既不进任何组，也不出现在结果里，导致「结果少了几组」这种静默错误。缺失也算一类时写 groupby(..., dropna=False)。"},{"h":"size() 与 count() 混用","d":"size() 数行数（含 NaN），count() 数非空值个数。用 count 当分母算比率会把「有缺失的行」排除在分母之外，比率因此虚高。"},{"h":"多对多 merge 导致的静默行数膨胀","d":"键不唯一时结果行数是 $\\sum_k \\text{cnt}_L(k)\\cdot\\text{cnt}_R(k)$，不报错、不告警，指标直接虚高。合并前必须 validate=\"one_to_many\" 之类的基数声明，或先 drop_duplicates。 正确做法：merge 前用 validate=\"one_to_many\" 声明基…"},{"h":"left.join(right) 默认按索引合并不是按列","d":"两边索引恰好相同时会静默错位对齐（左表第 1 行拿到右表第 1 行的值，那可能属于另一个实体），不报错、不出 NaN、看起来完全正常；索引不同时才会大面积 NaN。键在列里时必须 merge(on=\"id\") 或 join(right.set_index(\"id\"), on=\"id\")。"},{"h":"concat(axis=0) 是按列名对齐，不是按位置拼接","d":"两表列名不一致时会并出全部列并填 NaN，行数对但列数翻倍。想要按位置拼接必须统一列名或改用 numpy 拼接。"},{"h":"resample(\"ME\") 与 resample(\"MS\") 的标签差一个月","d":"M 把整月数据归到月末，MS 归到月初。月度报表用错会让所有数字都对、时间标签全错，是最难被发现的错误之一。"},{"h":"索引不单调就跑 rolling","d":"滑动窗口定义在「序」上，索引乱序时「最近 n 个」无定义。Pandas 会报错或给出错误结果。所有时间操作前先 df.sort_index() 并断言 index.is_monotonic_increasing。 正确做法：时间操作前先 sort_index()，并断言 index.is_monotonic_increasing。"}],"asks":[{"q":"groupby 之后有哪四种「聚合器」？怎么选？","a":"四种聚合器的区别只有一个维度：返回的形状。 | 方法 | 返回形状 | 索引 | 何时用 | |---|---|---|---| | agg | 每组一行 | 组标签 | 出报表 | | transform | 与原表同长 | 原索引 | 给原表加组级统计列 | | apply | 任意 | 你定 | 组内排序、多列联动等复杂逻辑 | | filter | 原表的行子集 | 原索引 | 只保留满足…","fu":["apply 一定比 agg 慢吗？","filter 和布尔索引有什么区别？"],"tag":"数据分析/后端"},{"q":"合并两张表时，什么情况下结果行数会变多？怎么防？","a":"一句话：键不唯一（多对多）时行数必然膨胀，而且不报错。 量化关系：对每个键 $k$，贡献 $\\text{cnt}_L(k) \\times \\text{cnt}_R(k)$ 行。所以结果行数 $= \\sum_k \\text{cnt}_L(k)\\cdot\\text{cnt}_R(k)$（inner）。 数学原因：连接的定义就是笛卡尔积再筛选，$|L \\times R| = |L| \\cdot |R|$…","fu":["validate 的四种取值分别对应什么基数关系？","如何用数据契约（如唯一约束）从根上避免这个问题？"],"tag":"数据分析/数据工程"},{"q":"resample 和 groupby 有什么本质区别？","a":"两者共享同一套 split-apply-combine 结构，区别在分组键的来源与稠密性： | | groupby | resample | |---|---|---| | 分组键 | 离散标签（列/Series） | 时间区间（由频率生成） | | 空区间 | 不产出（只出现过的组） | 产出空桶（值为 NaN） | | 索引 | 组标签 | DatetimeIndex | 「产出空桶」这一点是…","fu":["resample(\"M\") 和 resample(\"MS\") 的区别？","重采样后出现 NaN，怎么判断该填 0 还是该保留 NaN？"],"tag":"数据分析/金融科技"},{"q":"pivot_table 和 groupby 是什么关系？pivot 和 pivot_table 又有什么区别？","a":"第一问：pivot_table ≡ groupby(...).agg(f).unstack() python df.pivot_table(index=\"city\", columns=\"month\", values=\"sales\", aggfunc=\"sum\") # 完全等价于 df.groupby([\"city\", \"month\"])[\"sales\"].sum().unstack() 对应关系：…","fu":["crosstab 和 pivot_table 的关系？","normalize 参数在 crosstab 里做什么？"],"tag":"数据分析/商业分析"}]},{"id":"data-ch05","subj":"data","title":"数据采集：requests 与解析（含合规边界）","summary":"HTTP 在采集中的落地（请求方法、状态码、重定向、Session 与 Cookie）；requests 的参数/头/超时/重试/会话复用；解析方案对比（lxml+XPath 的性能、BeautifulSoup 的容错、正则的边界）；动态渲…","concepts":[{"id":"data-ch05/01-http-in-scraping","file":"01-http-in-scraping.md","title":"HTTP 在采集场景的落地","kind":"timeline","secs":[{"h":"一、请求方法、状态码与\"这份响应能不能用\"","s":"采集里 90% 用 GET。POST 出现在三类场景：搜索表单、接口分页（部分站点用 POST 传参）、登录。","c":{"lang":"python","code":"import requests\n\ndef fetch_usable(url: str, timeout=(3.05, 10)) -> str | None:\n    \"\"\"在采集里，「拿到响应」不等于「拿到能用的响应」。\"\"\"\n    resp = requests.get(url, timeout=timeout, allow_redirects=True)\n    if resp.status_code != 200:\n        return None                        # 4xx/5xx 就放弃，别硬解析错误页\n    ctype = resp.headers.get(\"Content-Type\", \"\")\n    if not ctype.startswith((\"text/html\", \"application/json\", \"text/xml\")):\n…"}},{"h":"二、重定向链、Cookie 与\"我到底请求了谁\"","s":"一次 requests.get(\"http://a.com/x\") 可能实际走成 http://a.com/x → https://a.com/x → https://www.a.com/x/。","c":null},{"h":"三、采集视角下\"响应内容不对\"的三种典型原因","s":"1. 内容压缩：响应是 gzip/br 压缩的，若客户端没声明 Accept-Encoding 或错误解码，拿到的就是乱码。requests 会自动处理，但自己拼 socket 时要注意。","c":null}]},{"id":"data-ch05/02-requests-in-depth","file":"02-requests-in-depth.md","title":"requests 实战：把\"能跑\"变成\"稳定\"","kind":"flow","secs":[{"h":"一、超时：必须显式设置，而且要设两个","s":"requests 默认没有超时——这是新手最常踩的坑：一个卡住的请求会让整个脚本挂死。","c":{"lang":"python","code":"resp = session.get(url, timeout=(3.05, 10))   # (连接超时, 读取超时)"}},{"h":"二、重试与退避：只重试\"值得重试的\"","s":"三条纪律：","c":{"lang":"python","code":"from requests.adapters import HTTPAdapter\nfrom urllib3.util.retry import Retry\n\nretry = Retry(\n    total=3,                      # 总重试次数\n    backoff_factor=0.5,           # 退避基数：0.5, 1, 2, 4 ... 秒\n    status_forcelist=(429, 500, 502, 503, 504),   # 只重试这些\n    allowed_methods=(\"GET\",),     # 幂等方法才安全重试\n    respect_retry_after_header=True,\n…"}},{"h":"三、会话复用与流式下载","s":"Session 解决两件事：","c":{"lang":"python","code":"with session.get(url, stream=True, timeout=(3.05, 30)) as r:\n    r.raise_for_status()\n    total = 0\n    for chunk in r.iter_content(chunk_size=8192):\n        if chunk:\n            total += len(chunk)"}},{"h":"四、一个\"守规矩\"的请求函数长什么样","s":"四点设计意图：限速在请求前（避免\"先打后等\"）、UA 表明身份（不伪装浏览器能减少对抗）、超时必填、尽早失败（raise_for_status）。","c":{"lang":"python","code":"def polite_get(session, url, *, delay=1.0, timeout=(3.05, 10)):\n    time.sleep(delay)                     # 主动限速，不是\"可选项\"\n    resp = session.get(url, timeout=timeout, headers={\"User-Agent\": UA})\n    resp.raise_for_status()               # 4xx/5xx 立即抛出，别让脏数据流到解析层\n    return resp"}}]},{"id":"data-ch05/03-parsing-and-encoding","file":"03-parsing-and-encoding.md","title":"解析与编码：把 HTML 变成结构化数据","kind":"compare","secs":[{"h":"一、解析三件套：lxml / BeautifulSoup / 正则","s":"实用组合：BeautifulSoup(html, \"lxml\") 或 lxml.html + CSS 选择器——拿 lxml 的速度，必要时退回 bs4 的容错。","c":null},{"h":"二、XPath 与 CSS 选择器的取舍","s":"定位表达式的健壮性排序：id > 稳定 data- 属性 > 语义 class > 结构位置（div:nth-child(3)）。","c":{"lang":"python","code":"from lxml import html\n\ndef picks(markup: str, xpath: str = \"//a/@href\") -> list[str]:\n    \"\"\"XPath 直接取属性/文本，比先取节点再取属性少一次往返。\"\"\"\n    doc = html.fromstring(markup)\n    return [v.strip() for v in doc.xpath(xpath) if v.strip()]\n\n# 同一件事的两种写法，结果一致但表达力不同\n#   XPath : //div[@class=\"item\"]/span[2]/text()\n…"}},{"h":"三、编码与乱码：三步定位法","s":"乱码只有三种成因，按此顺序排查：","c":null},{"h":"四、从表格到 DataFrame：一次性说清","s":"网页表格有两种形态，处理方式完全不同：","c":{"lang":"python","code":"import pandas as pd\nfrom lxml import html\n\ndef table_to_frame(markup: str, index: int = 0) -> pd.DataFrame:\n    \"\"\"取第 index 个 <table>：有 <th> 用 th 作表头，否则退回首行。\"\"\"\n    doc = html.fromstring(markup)\n    tables = doc.xpath(\"//table\")\n    if not tables:\n        raise ValueError(\"页面里没有 <table>\")\n…"}}]},{"id":"data-ch05/04-dynamic-pages-and-compliance","file":"04-dynamic-pages-and-compliance.md","title":"动态页面、工程化与合规红线","kind":"flow","secs":[{"h":"一、动态渲染：应对顺序不能颠倒","s":"页面看起来\"有数据但抓不到\"，按下面的顺序排查，不要一上来就上浏览器内核：","c":null},{"h":"二、工程化四件事：去重、限速、增量、可恢复","s":"1. 去重：用规范化后的 URL 或内容摘要作键。","c":null},{"h":"三、合规红线：这一节和技术同等重要","s":"采集前必须过的四道关，按顺序：","c":null},{"h":"四、把合规检查做成代码","s":"把\"人应该记得的事\"变成\"程序会拦住的事\"：","c":{"lang":"python","code":"FORBIDDEN_FIELDS = {\"id_card\", \"phone\", \"address\", \"real_name\"}   # 个人信息白名单外字段\n\ndef guard(record: dict, cfg: dict) -> dict:\n    out = {k: v for k, v in record.items() if k in cfg[\"allowed_fields\"]}   # 白名单\n    leaked = FORBIDDEN_FIELDS & set(out)\n    if leaked:\n        raise ValueError(\"命中个人信息字段，拒绝落盘: %s\" % sorted(leaked))\n    if not cfg.get(\"robots_ok\", False):\n        raise RuntimeError(\"未通过 robots 检查，禁止采集\")\n…"}}]}],"exams":[{"kind":"choice","q":"采集时遇到 403，最合理的处置是","stem":"在编写爬虫采集数据时，服务端返回 403 Forbidden。下列处置方式中最合理的是？","opts":[{"k":"A","t":"立即重试同一请求，直到返回 200"},{"k":"B","t":"更换 User-Agent 伪装成浏览器后再抓"},{"k":"C","t":"记录该 URL 与状态码后跳过，必要时通过站点公开接口或授权渠道获取"},{"k":"D","t":"提高并发数抢占配额，把请求压过去"}],"ans":"C","why":"403 表示服务端拒绝该请求。重试无意义；伪装 UA 规避限制属于绕过技术措施。正确做法是记录并跳过，必要时联系站点申请接口权限。"},{"kind":"choice","q":"关于 requests 的超时设置，正确的是","stem":"关于 Python requests 库的超时（timeout）设置，下列说法正确的是？","opts":[{"k":"A","t":"requests 默认有 30 秒超时，通常不需要显式设置"},{"k":"B","t":"timeout=5 表示整个请求（含重定向与下载）最多 5 秒"},{"k":"C","t":"不设 timeout 会一直挂住；传单个数字时连接与读取都用该值，读取超时衡量的是两次数据到达之间的间隔"},{"k":"D","t":"timeout 只对 GET 生效，POST 不受影响"}],"ans":"C","why":"requests 默认无超时（会永久挂住）；传单个数字等于连接与读取都用该值；读取超时衡量的是数据到达的间隔而非总时长；超时对所有方法生效。"},{"kind":"output","q":"服务器声明 charset=gb2312 但实际发送 UTF-8 字节，直接使用 resp.text 会怎样","stem":"服务器响应头声明 Content-Type: text/html; charset=gb2312，但实际发送的是 UTF-8 编码的字节。如果直接 resp.text 读取，会发生什么？如何正确拿到正确文本？","opts":[],"ans":"","why":"响应头的编码声明只是「建议」，真正决定字节的是服务端实际写出的编码。resp.text 直接用响应头/猜测的编码解码，一旦声明与实际不符就是乱码；且错误解码后再 encode 回不去原字节。因此永远先拿 resp.content（字节），再显式指定编码。"},{"kind":"fix_error","q":"下面的重试配置会带来生产风险，请指出并修正","stem":"下面的 requests 重试配置能跑通，但会带来生产风险。请指出风险并给出修正后的代码。","opts":[],"ans":"retry = Retry( total=3, status_forcelist=(429, 500, 502, 503, 504), allowed_methods=(\"GET\", \"HEAD\", \"PUT\", \"DELETE\"), backoff_factor=0.5, respect_retry_after_he…","why":"两类风险：① 400/403 是客户端错误，重试无意义且 403 重试加重风控，status_forcelist 应只含 429/5xx；② allowed_methods=None 让非幂等的 POST 也被重试，可能重复下单，应限定为 GET/HEAD/PUT/DELETE 或加幂等键。再补 backoff_factor 与 respect_retry_after_head…"},{"kind":"coding","q":"实现状态码分类函数，返回处置动作（PARSE/SKIP/FOLLOW/BACKOFF_RETRY/RETRY/DROP）","stem":"实现函数 action(code: int) -> str，依据 HTTP 状态码返回对应处置动作：200→PARSE、304→SKIP、3xx→FOLLOW、429→BACKOFF_RETRY、4xx→DROP、5xx→RETRY，其余→UNKNOWN。","opts":[],"ans":"def action(code: int) -> str: if code == 200: return \"PARSE\" if code == 304: return \"SKIP\" # 内容未变 if 300 <= code < 400: return \"FOLLOW\" if code == 429: return \"…","why":"分类依据是状态码首位：2xx→PARSE，304→SKIP，3xx→FOLLOW，429→BACKOFF_RETRY（尊重 Retry-After），4xx→DROP（我方错误重试无用），5xx→RETRY（服务端问题退避重试）。429 虽是 4xx 但语义特殊，必须单独处理。"},{"kind":"coding","q":"URL 去重的哈希思想（关联练习）","stem":"采集去重与「两数之和」共享同一核心：用哈希把 O(n²) 的两两比较降为 O(n) 的一次遍历。请说明采集场景下的映射关系与实现要点。（题面详见 external_url，不搬运。）","opts":[],"ans":"# 题面见 external_url（不搬运）。 # 关联要点：用 set 做已访问集合，先规范化 URL 再去重。 # 目标元素 -> 规范化后的 URL；哈希表 -> 已访问集合(set)；判重 -> URL 完全相等。","why":"采集去重与两数之和共享同一核心：用哈希把 O(n²) 降到 O(n)。映射：目标元素→规范化后的 URL；哈希表→已访问集合(set)；判重→URL 完全相等。关键是先规范化再入集合，否则参数顺序不同的同一 URL 会被当成两条。"},{"kind":"coding","q":"抓取队列的 BFS 与层序遍历的同构性","stem":"抓取调度与「二叉树层序遍历」共享同一 BFS 结构。请说明抓取队列与层序遍历的三点对应关系。（题面详见 external_url，不搬运。）","opts":[],"ans":"# 题面见 external_url（不搬运）。 # 关联要点：起始 URL 是根，页面链接是有向边，visited 是已访问标记。 # 队列保证按发现顺序访问；入队时判重避免重复入队；分层决定优先级与最大深度。","why":"抓取调度就是图的 BFS：起始 URL 是根，页面链接是有向边，visited 是已访问标记。队列保证按发现顺序访问；入队时判重避免重复入队（队列膨胀）；分层(depth)决定优先级与最大深度。"},{"kind":"output","q":"robots.txt 中同时有 Disallow: /private/ 与 Allow: /private/ok 时，/private/ok/a.html 允许吗","stem":"某站点 robots.txt 同时包含 Disallow: /private/ 与 Allow: /private/ok。问：/private/ok/a.html 是否被允许抓取？并说明判定规则与易错点。","opts":[],"ans":"","why":"robots 判定是最长匹配优先（RFC 9309），是前缀匹配而非目录匹配；长度相同时 Allow 优先；无匹配默认允许；robots.txt 只约束抓取、不授予内容使用权。"}],"works":[{"h":"requests 默认没有超时","d":"session.get(url) 在服务端不响应时会永久挂住（连接超时默认是内核级的、极长）。必须显式 timeout=(连接, 读取)，且两个都要设。"},{"h":"只设一个数字当超时","d":"timeout=10 等于连接与读取都用 10 秒。正确做法是元组 timeout=(3.05, 10)：连接快、读取可宽，两者语义完全不同。"},{"h":"重试 POST 导致重复提交","d":"通用重试无法区分\"请求没到\"与\"响应丢了\"，重试非幂等操作会造成重复下单/重复写入。只对 GET/HEAD/PUT/DELETE 等幂等方法重试。"},{"h":"把 4xx 也放进重试列表","d":"400（参数错）、401/403（无权限）、404（不存在）重试多少次都一样，只会浪费时间和加重风控。status_forcelist 只放 429 与 5xx。"},{"h":"不用 Session，每次新建连接","d":"丢掉 Cookie 持久与连接复用，抓几十页时代价明显，且需要手动传 Cookie，容易漏。"},{"h":"过早使用 resp.text","d":"一旦 text 解码错误（服务器声明编码有误或检测猜错），原始 bytes 的信息就丢了（错解不可逆）。军规：先存 resp.content，再显式解码。"},{"h":"迷信 resp.apparent_encoding","d":"它是基于内容统计的猜测，可能猜错。要兜底请用 charset_normalizer.from_bytes(raw).best()，并保留\"手动指定编码\"这条出口。"},{"h":"把浏览器里看到的 HTML 当成脚本拿到的 HTML","d":"浏览器有登录态、执行了 JS、可能带地域/语言差异。脚本看到的往往完全不同，view-source 才是可比对象。"}],"asks":[{"q":"给定一个「浏览器能看到数据、你的 requests 拿不到」，你会怎么排查？","a":"按「网络 → 表示 → 解析」三层排查，先查数据是怎么来的： 1. 看 Network 面板筛 XHR/Fetch：数据是不是 JSON 接口返回的？是 → 直接请求接口，问题结束。这是绝大多数情况。 2. 看 view-source：数据在原始 HTML 里吗？在 → 你的选择器写错了（常见是漏了 <tbody> 或 class 改名）。 3. 看 <script> 注入：有 window.__…","fu":["如果接口带签名参数怎么办？","无头浏览器抓取为什么『结果不确定』？"],"tag":"数据工程/后端"},{"q":"requests 默认没有超时，这会带来什么后果？timeout 传元组是什么意思？","a":"默认无超时意味着服务端不响应时请求会永久挂住（内核级超时极长），整个脚本线程被占死。 timeout=(连接超时, 读取超时)： - 连接超时：TCP 握手等待上限，公网 3~5 秒足够； - 读取超时：连接建立后，两次收到数据之间的最大间隔，不是总时长。所以大文件慢传不会被误杀，而「服务端挂住不回」会被及时掐断。 只写一个数字 = 两者都用该值，在「连接快但处理慢」的场景会误伤。 注意读取超时也…","fu":["连接超时在 TCP 层对应什么？","为什么说读取超时不是总时长？"],"tag":"后端/爬虫"},{"q":"哪些状态码该重试、哪些不该？为什么 429 要特殊处理？","a":"判据是「谁的错」： | 类别 | 处置 | |---|---| | 5xx（500/502/503/504） | 服务端问题 → 退避后重试 | | 429 | 限流 → 必须按 Retry-After 退避 | | 4xx 其他（400/401/403/404） | 我方错误 → 不重试 | | 304 | 内容未变 → 跳过解析 | 429 特殊是因为它明确告诉你「稍后再来」，硬打只会加重封禁…","fu":["幂等键（idempotency key）解决什么问题？","指数退避为什么比固定间隔好？"],"tag":"后端/分布式"},{"q":"为什么不能用正则解析 HTML？什么场景正则是正确的？","a":"正则无法表达任意深度的嵌套结构，这是形式语言理论中的结论：正则语言 ⊊ 上下文无关语言，正则不能计数嵌套层数。 具体失效模式（本章 ex07 有实证）：当某个条目缺少字段时，非贪婪的 .? 会跨过条目边界，把下一个条目的字段配给当前条目——产生静默错配，比报错更危险。 正则的正确场景： 1. 非 HTML 文本：<script> 里的 JSON 片段、JS 变量赋值； 2. 行级日志/CSV 这类…","fu":["如果页面是伪表格（div 拼的），你用什么抽？","怎么快速发现抽取规则失效了？"],"tag":"爬虫/数据工程"}]},{"id":"data-ch06","subj":"data","title":"数据分析与数学建模实战","summary":"数据清洗流程与质量检查清单；特征工程（缺失填充、异常检测、标准化/归一化、类别编码）；探索性分析（EDA）与可视化选型（分布/关系/时间/构成）；相关性分析与回归/分类的基本流程与评价指标；数学建模方法论（问题抽象、假设与符号、模型建立与求…","concepts":[{"id":"data-ch06/01-cleaning-and-quality-checks","file":"01-cleaning-and-quality-checks.md","title":"数据清洗与质量体检","kind":"flow","secs":[{"h":"一、质量体检清单：六项必查","s":"拿到任何一份表，按固定顺序跑一遍，产出\"问题清单 + 处置方案\"：","c":{"lang":"python","code":"import pandas as pd\n\ndef profile(df: pd.DataFrame) -> pd.DataFrame:\n    rows = []\n    for col in df.columns:\n        s = df[col]\n        rows.append({\n            \"列\": col,\n            \"类型\": str(s.dtype),\n…"}},{"h":"二、缺失值：先判断机制，再决定动作","s":"三种缺失机制，决定你能不能用\"删\"：","c":{"lang":"python","code":"import pandas as pd\n\ndef missing_report(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"缺失率只看比例会误判：还要区分 dtype 与「是否与目标相关」。\"\"\"\n    out = pd.DataFrame({\n        \"missing\": df.isna().sum(),\n        \"ratio\": df.isna().mean().round(4),\n        \"dtype\": df.dtypes.astype(str),\n    })\n…"}},{"h":"三、异常检测：三种判据及其假设","s":"三条纪律：","c":null},{"h":"四、去重与一致性：最容易被低估的一步","s":"精确重复用 drop_duplicates()；但真实数据里更多是近似重复：","c":null}]},{"id":"data-ch06/02-feature-engineering","file":"02-feature-engineering.md","title":"特征工程与数据泄漏","kind":"flow","secs":[{"h":"一、缩放：哪些模型必须做，为什么","s":"原因很直白：距离 $d=\\sqrt{\\sum(x_i-y_i)^2}$ 会被量纲大的特征支配。以\"年龄(0~100)\"与\"收入(0~10^6)\"为例，","c":{"lang":"python","code":"import numpy as np\nfrom sklearn.preprocessing import MinMaxScaler, RobustScaler, StandardScaler\n\nage    = np.array([23, 31, 45, 52, 61], dtype=float)\nincome = np.array([8e3, 1.2e4, 2.1e4, 3.0e4, 9.9e7], dtype=float)  # 末位是录入错误\nX = np.column_stack([age, income])\n\nfor name, sc in [(\"minmax\", MinMaxScaler()),\n                 (\"zscore\", StandardScaler()),\n…"}},{"h":"二、类别编码：三种方式与各自的风险","s":"一条硬纪律：任何用到目标变量 $y$ 的编码（目标编码），都必须在训练集上计算、且不能包含当前样本自己的 $y$。","c":null},{"h":"三、数据泄漏：三个真实场景","s":"泄漏 = 训练时用到了预测时不可能获得的信息。三种最常见：","c":{"lang":"python","code":"import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nX, y = make_classification(n_samples=600, n_features=20, n_informative=5, random_state=0)\n…"}},{"h":"四、派生特征与分箱","s":"四类高性价比派生：","c":null}]},{"id":"data-ch06/03-eda-and-visualization","file":"03-eda-and-visualization.md","title":"EDA 与可视化选型","kind":"compare","secs":[{"h":"一、EDA 的三层提问法","s":"按\"单变量 → 双变量 → 多变量\"三层推进，每层只问一件事：","c":{"lang":"python","code":"import pandas as pd\n\ndef describe_one(s: pd.Series) -> dict:\n    q1, q3 = s.quantile([0.25, 0.75])\n    iqr = q3 - q1\n    return {\n        \"n\": int(s.notna().sum()),\n        \"mean\": round(float(s.mean()), 3),\n        \"median\": round(float(s.median()), 3),\n…"}},{"h":"二、按\"要表达什么关系\"选图","s":"三条实操建议：","c":null},{"h":"三、相关系数三法：Pearson / Spearman / 互信息","s":"实践顺序：先散点图，再选系数。只算 Pearson 就下结论是\"漏掉非线性关系\"的主要来源。","c":null},{"h":"四、把图表结论落到数字","s":"图表给\"形状\"，数字给\"判据\"。每一张图都应该能转成一句带数字的结论，例如：","c":null}]},{"id":"data-ch06/04-modeling-metrics-and-math-modeling","file":"04-modeling-metrics-and-math-modeling.md","title":"建模流程、评价指标与数学建模方法论","kind":"timeline","secs":[{"h":"一、建模流程：八步不可跳","s":"两个最容易被跳掉、却最重要的步骤：","c":{"lang":"text","code":"① 明确目标与评价口径  → ② 划分数据（时间序务必按时间切）\n   → ③ 建立基线（先跑最笨的模型） → ④ 迭代特征与模型\n   → ⑤ 交叉验证调参 → ⑥ 在留出集上评估 → ⑦ 误差分析\n   → ⑧ 结论 + 局限 + 灵敏度"}},{"h":"二、回归评价指标：五个数各自的脾气","s":"三条纪律：","c":{"lang":"python","code":"import numpy as np\n\ndef regression_metrics(y_true, y_pred) -> dict:\n    y_true, y_pred = np.asarray(y_true, float), np.asarray(y_pred, float)\n    err = y_true - y_pred\n    ss_res = float((err ** 2).sum())\n    ss_tot = float(((y_true - y_true.mean()) ** 2).sum())\n    return {\n        \"MAE\": float(np.abs(err).mean()),\n…"}},{"h":"三、分类评价指标：准确率的陷阱","s":"先有混淆矩阵（以正类为关注对象）：","c":{"lang":"python","code":"from sklearn.metrics import precision_recall_fscore_support, roc_auc_score\n\ndef best_threshold(y_true, y_score, beta: float = 1.0) -> dict:\n    \"\"\"按业务取向选阈值：beta>1 偏召回，beta<1 偏精确，而不是默认 0.5。\"\"\"\n    best_thr, best_fb = None, -1.0\n    for thr in [i / 100 for i in range(1, 100)]:\n        pred = (y_score >= thr).astype(int)\n        p, r, _, _ = precision_recall_fscore_support(\n            y_true, pred, average=\"binary\", zero_division=0)\n…"}},{"h":"四、数学建模：把开放题答成规范报告","s":"数学建模题的评分结构几乎是固定的五段，缺一段就明显掉档：","c":{"lang":"python","code":"import numpy as np\n\ndef residual_diagnosis(y_true, y_pred) -> dict:\n    \"\"\"残差三看：均值是否为 0、是否随预测值扩散、是否有极端离群。\"\"\"\n    r = np.asarray(y_true, float) - np.asarray(y_pred, float)\n    corr = float(np.corrcoef(np.asarray(y_pred, float), np.abs(r))[0, 1])\n    q1, q3 = np.percentile(r, [25, 75])\n    iqr = q3 - q1\n    outliers = int(((r < q1 - 1.5 * iqr) | (r > q3 + 1.5 * iqr)).sum())\n…"}}]}],"exams":[{"kind":"choice","q":"关于缺失值机制，正确的是","stem":"某订单表「收货城市」字段缺失 12%。业务核查后确认：缺失与否与订单金额、用户等级、下单时间、注册渠道均无关，也无法由任何已观测字段预测。团队准备直接删除这 12% 的行。 关于该缺失机制与「直接删除」的后果，下列说法正确的是？","opts":[{"k":"A","t":"只要缺失比例不高，无论哪种机制，删除缺失行都不会引入偏差"},{"k":"B","t":"MCAR 下删除缺失行只损失样本量、不引入偏差；MAR 指缺失与已观测变量有关；MNAR 无法用数据自证"},{"k":"C","t":"MAR 指缺失与缺失值本身有关，可以直接用均值填充"},{"k":"D","t":"填充策略与缺失机制无关，选均值填充总是安全的"}],"ans":"B","why":"MCAR（完全随机缺失）下删除只损失样本量、不引入偏差；MAR 是缺失与其他已观测变量有关；MNAR 无法用数据自证，只能靠业务判断。填充策略必须随机制调整。"},{"kind":"choice","q":"下列哪个模型不必须做特征缩放","stem":"一份含 20 个特征的数据集里，有的特征量级是 $10^5$（金额），有的是 $10^{-2}$（比率）。现在用同一份数据分别训练 KNN、RBF 核 SVM、决策树、PCA，不删特征、只考虑要不要先做缩放。 下列判断中，正确的是？","opts":[{"k":"A","t":"KNN"},{"k":"B","t":"RBF 核 SVM"},{"k":"C","t":"决策树"},{"k":"D","t":"PCA"}],"ans":"C","why":"决策树的分裂只依赖单个特征上的样本排序，对单调变换不变，因此缩放不改变分裂结果。KNN/SVM/PCA 都基于距离或内积，量纲会被大尺度特征支配，必须缩放。"},{"kind":"output","q":"某二分类任务正类占 1%，模型把所有样本判为负类，准确率、召回率、F1 分别是多少","stem":"某二分类任务共 1000 个样本，正类占 1%（10 个），负类 990 个。模型把全部样本判为负类。 请给出准确率、召回率、精确率、F1 四个值（精确率按工程约定处理），并判断这个模型能否上线。","opts":[],"ans":"","why":"这是「准确率陷阱」的标准形态：98% 的负类让常数预测器也有 99% 准确率。不平衡场景应看召回率、F1 或 PR-AUC；精确率的分母是「预测为正的总数」，本题为 0，所以按约定记 0 而不是报错。"},{"kind":"fix_error","q":"下面的特征工程流程存在数据泄漏，请指出并修正","stem":"下面的特征工程 + 建模流程能跑通，但存在数据泄漏。X 是特征矩阵、y 是标签： python mu = X.mean(axis=0) sd = X.std(axis=0) X_scaled = (X - mu) / sd X_train, X_test, y_train, y_test = train_test_split(X_scaled, y, test_size=0.3) model.fi…","opts":[],"ans":"from sklearn.model_selection import train_test_split # 需 scikit-learn X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3, random_state=0) m…","why":"泄漏点是 mu/sd 用了全量数据（含测试集），测试集的分布信息提前进入训练流程，离线指标被系统性高估、线上会掉。正确顺序是先划分再 fit。同一原则适用于缺失值填充、类别编码（目标编码尤甚）、特征选择、降采样/过采样——凡是「需要用数据估计参数」的步骤，参数只能在训练集上 fit。"},{"kind":"coding","q":"手写 IQR 异常检测函数，返回上下界与异常掩码","stem":"用 pandas 实现异常检测函数 iqr_outliers(s, k=1.5)： - 输入：数值型 pandas.Series 与系数 k； - 输出：(lo, hi, mask)，mask 为布尔 Series，标记越界点； - 边界取 Q1 - kIQR 与 Q3 + kIQR，必须用分位数，不得用均值/标准差。 并回答：k=1.5 在正态分布下的越界概率约为多少？为什么右偏分布上 IQR…","opts":[],"ans":"import pandas as pd def iqr_outliers(s, k=1.5): q1, q3 = s.quantile(0.25), s.quantile(0.75) iqr = q3 - q1 lo, hi = q1 - k iqr, q3 + k iqr return lo, hi, (s < lo…","why":"k=1.5 是 Tukey 的经验取值，正态下越界概率约 0.7%（约等于 |z|>2.7）。IQR 用分位数替代均值与标准差，而均值/标准差会被极端值本身拉大（掩蔽效应），导致重尾分布上极端点反而不超阈值；分位数不受此影响，所以对偏态更稳健。返回上下界而不只是掩码，便于后续截断或写报告。"},{"kind":"coding","q":"异常区间的最大和检测（关联练习）","stem":"「异常区间检测」与「最大子数组和」是同构问题：把每个时刻相对基线的偏离 d_t = x_t - mean(x) 当作数组元素，求最大子数组和即得到偏离最严重的连续区间。 请回答： 1. 写出映射关系：数组元素、目标、边界条件分别对应什么； 2. 给出 O(n) 时间、O(1) 空间的 Kadane 实现，并说明它为什么不需要额外数组； 3. 比较区间方法与逐点方法（Z-score / IQR）：什…","opts":[],"ans":"def max_offset_window(xs): \"\"\"返回 (最大偏离和, (起, 止))；偏离 = 相对均值的差。\"\"\" n = len(xs) if n == 0: return 0.0, (0, 0) m = sum(xs) / n d0 = xs[0] - m best = cur = d0 best_s…","why":"Kadane 的关键是「以 i 结尾的最大和」只依赖「以 i-1 结尾的最大和」，所以一个滚动变量就够，不需要 DP 数组，空间 O(1)。区间方法识别的是持续性整体偏移（系统性偏高/偏低一段），逐点方法只看单点偏离，遇到「每点轻微偏高但都不超阈值」时会整段漏报，同时也更容易被单点尖峰占满告警。"},{"kind":"coding","q":"分位数的高效计算（关联练习）","stem":"分位数是 IQR 异常检测与箱线图的基础，它的计算与「第 K 大」同源。请回答： 1. 三种实现路线（完整排序、快速选择 quickselect、流式近似 P²/t-digest）的复杂度与适用场景； 2. 为什么数据采集/清洗管道常必须用流式近似分位数； 3. 实现 kth_largest(xs, k)（k 从 1 开始），要求平均 O(n) 且不使用 sorted。 在线练习：牛客网 · 第…","opts":[],"ans":"import random def kth_largest(xs, k): \"\"\"第 k 大（k=1 即最大值），平均 O(n)。\"\"\" if not 1 <= k <= len(xs): raise ValueError('k 越界') target = len(xs) - k # 转成第 target 小 a =…","why":"排序 O(n log n) 简单但要对全量数据排序；quickselect 每次只递归一半，期望 O(n)、最坏 O(n^2)（可用随机枢轴或 median-of-medians 压住）；流式近似单遍扫描、O(1) 或 O(1/eps) 空间，用精度换资源。管道里数据量超出内存、且要求单遍到达即出结果，所以只能选近似算法。第 k 大转成第 (n-k) 小后套 quicksele…"},{"kind":"output","q":"为什么最小化 MAE 得到的是中位数，最小化 RMSE 得到的是均值","stem":"同一个回归任务，把损失从 MSE 换成 MAE，最优的常数预测会从均值变成中位数。 请回答： 1. 用求导说明：为什么最小化 MAE 得到中位数、最小化 MSE 得到均值； 2. 若目标变量右偏（订单金额、会话时长），这两个选择分别会导致系统性高估还是低估； 3. 业务方说「要看平均消耗」时，应该选哪个损失与指标？","opts":[],"ans":"","why":"核心是「指标选择即目标函数选择，也就决定了你在预测哪个条件统计量」。右偏分布下均值被长尾拉高，中位数不受影响，因此同一份数据用两种损失训练，常数预测会差出一个可观的距离。报告时必须写清口径，否则同一模型会被算出两套互相矛盾的结论。"}],"works":[{"h":"先填缺失再判断机制","d":"不判断 MCAR/MAR/MNAR 就填均值，在 MNAR 下必然引入偏差。MNAR 无法用数据自证，只能靠业务知识判断，且删除会系统性偏差。"},{"h":"均值填充后照常报告方差与相关性","d":"均值填充把方差压缩为原来的 $n_{obs}/n$，相关系数随之被衰减。填完之后必须说明口径，别拿\"填充后的统计量\"当\"真实统计量\"。"},{"h":"用 Z-score 检测右偏数据的异常","d":"金额、时长这类右偏分布下，$\\mu$ 和 $\\sigma$ 被大值拉偏，产生掩蔽效应：真正的极端值反而不超阈值。默认选 IQR，或用中位数+MAD 的 Robust Z-score。"},{"h":"把异常值直接删掉","d":"异常可能是真信号（欺诈、故障、爆款）。先看业务含义，且保留原始列（新增 _clean 列而不是就地覆盖）。"},{"h":"Min-Max 归一化用在有极端值的数据上","d":"单个极值会把其余所有点压缩到极小的区间内，信息几乎全丢。有异常值时用 Robust 缩放。"},{"h":"对决策树做特征缩放并期待效果变化","d":"树分裂只依赖单特征上的排序，对单调变换不变，缩放不会改变分裂结果。反过来，距离类模型（KNN/K-means/SVM/PCA）必须缩放，否则距离被大量纲特征支配。"},{"h":"把\"标准化\"和\"归一化\"当同义词","d":"标准化 = Z-score（均值 0 方差 1）；归一化 = Min-Max（映射到 $[0,1]$）。混用会导致方法选错。"},{"h":"无序类别用序号编码","d":"把\"北京/上海/广州\"编码成 1/2/3，会强加\"广州 > 上海 > 北京\"的虚假顺序，线性模型据此产生无意义的外推。"}],"asks":[{"q":"拿到一份新数据，你的清洗流程是什么？","a":"先诊断、再处置、必留痕、后复检，四步不可跳： 1. 质量体检六项：完整性（缺失率）、唯一性（重复行/近似重复）、有效性（类型/格式）、一致性（同义异名/单位）、准确性（越界值）、时效性（时间范围/时区）。 2. 缺失机制判断：MCAR（可删）/ MAR（可分组填）/ MNAR（删除必有偏，只能靠业务判断）。工程兜底是保留缺失 + 加 _is_missing 标记列。 3. 处置：新增 xxx_cl…","fu":["MNAR 为什么无法用数据自证？","均值填充对方差和相关性有什么影响？"],"tag":"数据分析/数据工程"},{"q":"为什么 KNN 需要归一化而决策树不需要？","a":"因为距离对量纲敏感，而分裂点对量纲不敏感。 - KNN/SVM/K-means/PCA 都基于距离或内积。以「年龄(0~100)」与「收入(0~10^6)」为例，距离几乎完全由收入决定，年龄信息被淹没。缩放是在修正度量，让各维等权。 - 决策树只在单个特征上找分裂点，判据（如基尼不纯度下降）只依赖样本在该维上的排序。单调变换保持排序，所以缩放不改变任何分裂结果。 补充两点： 1. 树模型虽不必缩放…","fu":["Min-Max 在有极端值时有什么问题？","标准化和归一化有什么区别？"],"tag":"算法/数据分析"},{"q":"什么是数据泄漏？请举三个具体例子。","a":"泄漏 = 训练时用到了预测时不可能获得的信息，导致离线指标被系统性高估。三个典型： 1. 时间穿越：用全量数据的统计量填充/标准化后再按时间划分——等于用未来填过去。正解是按时间切分，统计量只用历史。 2. 预处理泄漏：先对全量做标准化/填充/特征选择，再划分训练测试。测试集的 $\\mu,\\sigma$ 信息进了训练。正解是所有 fit 只在训练集（Pipeline 就是为此设计）。 3. 目标编…","fu":["为什么说泄漏坏掉的是你对模型的判断而非模型本身？","嵌套交叉验证解决什么问题？"],"tag":"算法/数据分析"},{"q":"类别不平衡时为什么不能用准确率？该看什么指标？","a":"准确率把四类结果一视同仁，而不平衡任务里判对负类太容易了。 正类占 1% 时，全判负类就有 99% 准确率，但召回率为 0、F1 为 0——这个「好指标」毫无业务价值。 该看的指标取决于错误代价： | 场景 | 首选指标 | 理由 | |---|---|---| | 误报代价高（垃圾邮件误杀） | 精确率 | 宁可漏，不可错杀 | | 漏报代价高（疾病筛查、欺诈初筛） | 召回率 | 宁可错，不可…","fu":["AUC 的概率含义是什么？","PR-AUC 与 ROC-AUC 在不平衡时有什么差别？"],"tag":"算法/数据分析"}]}];

export default CHAPTERS;
